// Step-by-step worked solutions for the ACT2 exams (keyed by exam id, then question number).
// The final "Answer" line is added automatically from each question's correct option.
export const ACT2_SOLUTIONS: Record<string, Record<string, string>> = {
 "act2_3d_exam1": {
  "1": "**Step 1:** Circle area: $\\pi r^2 = 20 \\Rightarrow r^2 = \\frac{20}{\\pi} \\Rightarrow r = \\sqrt{\\frac{20}{\\pi}}$.\n**Step 2:** Circumference: $C = 2\\pi r = 2\\pi\\sqrt{\\frac{20}{\\pi}} = 2\\sqrt{20\\pi}$.\n**Step 3:** The square's perimeter equals $C$: $4s = 2\\sqrt{20\\pi} \\Rightarrow s = \\frac{\\sqrt{20\\pi}}{2}$.\n**Step 4:** Area of the square: $s^2 = \\frac{20\\pi}{4} = 5\\pi$.",
  "2": "**Step 1:** The belt makes both circles' rims travel the same distance: (circumference $\\times$ turns) is equal for both.\n**Step 2:** Large circle: $2\\pi(5)(10) = 100\\pi$ ft of belt.\n**Step 3:** Small circle: $2\\pi(2)\\,n = 100\\pi \\Rightarrow 4n = 100 \\Rightarrow n = 25$ turns. (The $9$ ft distance is not needed.)",
  "3": "**Step 1:** Let $p$ = pounds of peanuts, so cashews $= 10 - p$.\n**Step 2:** Total value of the mixture: $5.45 \\times 10 = 54.50$ dollars.\n**Step 3:** $3.75p + 8(10 - p) = 54.5 \\Rightarrow 3.75p + 80 - 8p = 54.5$.\n**Step 4:** $-4.25p = -25.5 \\Rightarrow p = 6$ pounds of peanuts.",
  "4": "**Step 1:** Let $w$ be the sidewalk width. The outer rectangle is $(4 + 2w)$ by $(6 + 2w)$.\n**Step 2:** $(4 + 2w)(6 + 2w) = 40 \\Rightarrow 24 + 20w + 4w^2 = 40 \\Rightarrow 4w^2 + 20w - 16 = 0 \\Rightarrow w^2 + 5w - 4 = 0$.\n**Step 3:** Quadratic formula: $w = \\frac{-5 \\pm \\sqrt{25 + 16}}{2} = \\frac{-5 \\pm \\sqrt{41}}{2}$.\n**Step 4:** A width must be positive, so $w = \\frac{-5 + \\sqrt{41}}{2}$.",
  "5": "**Step 1:** Simple interest: $I = Prt$.\n**Step 2:** $I = 5000 \\times 0.03 \\times t = 150t$ dollars.",
  "6": "**Step 1:** From the table, $y$ doubles each time $x$ increases by $1$, starting from $y = 1$ at $x = 0$: $y = 2^x$.\n**Step 2:** At $x = 10$: $y = 2^{10} = 1024$.",
  "7": "**Step 1:** The three angles of the triangle are $30^\\circ$, $X$ and $Y$, so $30 + X + Y = 180 \\Rightarrow X + Y = 150$.\n**Step 2:** Substitute $X = 2Y$: $3Y = 150 \\Rightarrow Y = 50^\\circ$.\n**Step 3:** $X = 2(50^\\circ) = 100^\\circ$.",
  "8": "**Step 1:** $\\angle ACE$ is an inscribed angle whose intercepted arc is $\\overset{\\frown}{AED}$ (arc $AE$).\n**Step 2:** An inscribed angle equals half its intercepted arc: $\\frac{84^\\circ}{2} = 42^\\circ$.",
  "9": "**Step 1:** For similar solids, if lengths are multiplied by $k$, volumes are multiplied by $k^3$.\n**Step 2:** $k = 3 \\Rightarrow$ volume ratio $= 3^3 = 27$.\n**Step 3:** The second planter needs $27$ bags of soil.",
  "10": "**Step 1:** Translate the relationship: the $y$-coordinate is $3$ less than half of the $x$-coordinate.\n**Step 2:** Half of $x$ is $\\frac{1}{2}x$; $3$ less than that is $\\frac{1}{2}x - 3$.\n**Step 3:** So $y = \\frac{1}{2}x - 3$.",
  "11": "**Step 1:** $\\triangle ABC$ is a right isosceles triangle with legs $AB = AC = 1$.\n**Step 2:** Hypotenuse $BC = \\sqrt{1^2 + 1^2} = \\sqrt{2}$, which is also the side of square $BCED$.\n**Step 3:** The outer boundary $A \\to B \\to D \\to E \\to C \\to A$ uses $AB$, $BD$, $DE$, $EC$, $CA$: $1 + \\sqrt{2} + \\sqrt{2} + \\sqrt{2} + 1 = 2 + 3\\sqrt{2}$.",
  "12": "**Step 1:** One diagonal of the rectangle runs from the center to a point on the circle, so it is a radius $= 2$.\n**Step 2:** The diagonals of a rectangle are congruent, so the other diagonal $AB$ also equals $2$.\n**Step 3:** All three statements are used, so the answer is “All the above”.",
  "13": "**Step 1:** A regular hexagon is made of $6$ equilateral triangles with side $s = 4$.\n**Step 2:** Area of one triangle: $\\frac{\\sqrt{3}}{4}s^2 = \\frac{\\sqrt{3}}{4}(16) = 4\\sqrt{3}$.\n**Step 3:** Hexagon: $6 \\times 4\\sqrt{3} = 24\\sqrt{3} \\approx 41.6\\text{ m}^2$.",
  "14": "**Step 1:** Join the three centers: they form an equilateral triangle of side $2r = 6$, parallel to the outer triangle's sides.\n**Step 2:** Each outer side = $6$ (between tangent points) $+ 2 \\times$ (corner piece). In each $30$-$60$-$90$ corner, the piece is $r\\sqrt{3} = 3\\sqrt{3}$.\n**Step 3:** Side $= 6 + 6\\sqrt{3}$, so perimeter $= 3(6 + 6\\sqrt{3}) = 18 + 18\\sqrt{3}$.",
  "15": "**Step 1:** Compound interest: $A = P(1 + r)^t$.\n**Step 2:** $P = 5000$, $r = 0.32$: $A = 5000(1.32)^t$.",
  "16": "**Step 1:** Substitute $y = x + 4$ into $2x - y = 12$: $2x - (x + 4) = 12$.\n**Step 2:** $x - 4 = 12 \\Rightarrow x = 16$.\n**Step 3:** $y = 16 + 4 = 20$.",
  "17": "**Step 1:** Division first: $8 \\div 2 = 4$, so $-6x - 4 - (4x - 5)$.\n**Step 2:** Distribute the minus sign: $-6x - 4 - 4x + 5$.\n**Step 3:** Combine like terms: $-10x + 1$.",
  "18": "**Step 1:** Test each choice with numbers, e.g. $x = 1$, $y = 2$: A gives $\\frac{1}{2} \\ne 2$, B gives $-1 \\ne 1$, C gives $5 \\ne 4$.\n**Step 2:** D: $2x + 3y = 3y + 2x$ is the commutative property of addition — true for all $x$, $y$.",
  "19": "**Step 1:** In a geometric sequence the middle term is the geometric mean of its neighbours: $n^2 = 16 \\times 36 = 576$.\n**Step 2:** $n = \\sqrt{576} = 24$ (ratio $\\frac{3}{2}$: $16, 24, 36$).",
  "20": "**Step 1:** Ann starts with $x + 5$ dollars.\n**Step 2:** After giving John $10$ dollars: $(x + 5) - 10 = x - 5$.",
  "21": "**Step 1:** Decrease $= 10.7 - 9.3 = 1.4$ million.\n**Step 2:** Percent decrease $= \\frac{1.4}{10.7} \\times 100\\% \\approx 13.1\\%$, closest to $13\\%$.",
  "22": "**Step 1:** For consecutive numbers, the average is the middle number, so the middle one is $12$.\n**Step 2:** The numbers are $10, 11, 12, 13, 14$; the largest is $14$.",
  "23": "**Step 1:** $5|8 - 2x| > 30 \\Rightarrow |8 - 2x| > 6$.\n**Step 2:** Case 1: $8 - 2x > 6 \\Rightarrow -2x > -2 \\Rightarrow x < 1$.\n**Step 3:** Case 2: $8 - 2x < -6 \\Rightarrow -2x < -14 \\Rightarrow x > 7$.\n**Step 4:** Solution: $x < 1$ or $x > 7$.",
  "24": "**Step 1:** $\\frac{1}{3^x}$ is the reciprocal of $3^x$.\n**Step 2:** A number times its reciprocal equals $1$: this is the Multiplicative Inverse Property.",
  "25": "**Step 1:** Since $x > y > 1$: $\\frac{1}{x}$, $\\frac{1}{y}$ and $\\frac{1}{x - y}$ are all positive.\n**Step 2:** $y - x < 0$, so $\\frac{1}{y - x}$ is negative — the least value.",
  "26": "**Step 1:** Regular price $= 80\\%$ of list $= 0.80L$.\n**Step 2:** Sale takes another $10\\%$ off: $0.90 \\times 0.80L = 0.72L$.\n**Step 3:** The sale price is $72\\%$ of the list price.",
  "27": "**Step 1:** Each price includes $20\\%$ extra, so price $= 1.20 \\times$ (base price).\n**Step 2:** Difference of the totals: $5.40 - 4.80 = 0.60$.\n**Step 3:** Difference of the base prices: $\\frac{0.60}{1.20} = 0.50$, i.e. \\$0.50.",
  "28": "**Step 1:** Let the price be $P$. $20\\%$ off saves $0.20P$.\n**Step 2:** $0.20P = 20 \\Rightarrow P = \\frac{20}{0.20} = 100$, i.e. \\$100.",
  "29": "**Step 1:** Distances from $6.06$: to $6.1$ is $0.04$; to $6$ is $0.06$; to $6.7$ is $0.64$; to $7$ is $0.94$.\n**Step 2:** The smallest distance is to $6.1$.",
  "30": "**Step 1:** Compare each with $\\frac{1}{2}$: $\\frac{101}{200} > \\frac{100}{200}$, $\\frac{17}{33} > \\frac{16.5}{33}$, $\\frac{7}{12} > \\frac{6}{12}$.\n**Step 2:** $\\frac{60}{1000} = 0.06 < 0.5$ — the exception.",
  "31": "**Step 1:** $\\frac{1}{4}x > 8$.\n**Step 2:** Multiply both sides by $4$: $x > 32$.",
  "32": "**Step 1:** Time: $2$ h $18$ min $30$ s $= 2 + \\frac{18.5}{60} \\approx 2.3083$ hours.\n**Step 2:** Speed $= \\frac{510}{2.3083} \\approx 220.9 \\approx 221$ miles per hour.",
  "33": "**Step 1:** Numbers of the form $4N + 1$ leave remainder $1$ when divided by $4$.\n**Step 2:** $55 \\to 3$, $62 \\to 2$, $71 \\to 3$, $93 \\to 1$.\n**Step 3:** $93 = 4(23) + 1$.",
  "34": "**Step 1:** $3(-3)^2 + 5(-3) + 6 = 3(9) - 15 + 6$.\n**Step 2:** $= 27 - 15 + 6 = 18$.",
  "35": "**Step 1:** The figure shows a right angle at $B$ (between $\\overrightarrow{BA}$ and $\\overrightarrow{BC}$) split into $12x^\\circ$ and $(2x + 9)^\\circ$.\n**Step 2:** Two angles that together make a right angle are complementary: $(2x + 9) + 12x = 90$.",
  "36": "**Step 1:** $1.75$ millionaires per $1000$ people.\n**Step 2:** $8{,}000{,}000 \\div 1000 = 8000$ groups of $1000$.\n**Step 3:** $8000 \\times 1.75 = 14{,}000$ millionaires.",
  "37": "**Step 1:** Interior angle sum $= (n - 2) \\times 180^\\circ$.\n**Step 2:** Hexagon: $n = 6 \\Rightarrow 4 \\times 180^\\circ = 720^\\circ$.",
  "38": "**Step 1:** $x + y = 1 \\Rightarrow y = -x + 1$: slope $= -1$, $y$-intercept $= 1$.\n**Step 2:** $x$-intercept (set $y = 0$): $x = 1$.\n**Step 3:** Sum $= -1 + 1 + 1 = 1$.",
  "39": "**Step 1:** Angles of incidence and reflection at the mirror are equal, so $\\triangle ABM \\sim \\triangle CDM$ (both have right angles).\n**Step 2:** $\\frac{AB}{BM} = \\frac{CD}{DM} \\Rightarrow \\frac{5}{4} = \\frac{h}{28}$.\n**Step 3:** $h = \\frac{5 \\times 28}{4} = 35$ ft.",
  "40": "**Step 1:** Both triangles have angles $55^\\circ$, $60^\\circ$, $65^\\circ$, so they are similar (AA).\n**Step 2:** The $4$ m side lies opposite different angles in the two triangles, so corresponding sides are not equal — they are not congruent.",
  "41": "**Step 1:** The net has $8$ equilateral triangles: a regular octahedron.\n**Step 2:** Edges $= \\frac{8 \\text{ faces} \\times 3 \\text{ sides}}{2} = 12$ (each edge is shared by two faces).",
  "42": "**Step 1:** Total cards $= 9 + 7 = 16$.\n**Step 2:** $P(\\text{white}) = \\frac{9}{16}$.",
  "43": "**Step 1:** $C = \\pi d$.\n**Step 2:** $C = 11\\pi$ inches.",
  "44": "**Step 1:** The cutting plane is parallel to the cone's circular base.\n**Step 2:** A cross section parallel to the base of a cone is a circle.",
  "45": "**Step 1:** $(2x^3y^5z)^3 = 2^3x^9y^{15}z^3 = 8x^9y^{15}z^3$.\n**Step 2:** Multiply by $2$: $16x^9y^{15}z^3$.",
  "46": "**Step 1:** $\\left(\\frac{1}{3}p^2q^5\\right)^2 = \\frac{1}{9}p^4q^{10}$.\n**Step 2:** $-2pq^3 \\cdot \\frac{1}{9}p^4q^{10} = -\\frac{2}{9}p^5q^{13}$.",
  "47": "**Step 1:** $r = \\frac{17}{2} = 8.5$.\n**Step 2:** $A = \\pi r^2 = 72.25\\pi \\approx 226.98 \\approx 227$.",
  "48": "**Step 1:** $25x^2 - 121 = (5x)^2 - 11^2$ is a difference of squares.\n**Step 2:** $a^2 - b^2 = (a - b)(a + b) \\Rightarrow (5x - 11)(5x + 11)$.",
  "49": "**Step 1:** Pythagorean theorem with legs $\\sqrt{x}$ and $2\\sqrt{3}$, hypotenuse $x$: $x + 12 = x^2$.\n**Step 2:** $x^2 - x - 12 = 0 \\Rightarrow (x - 4)(x + 3) = 0$.\n**Step 3:** Length is positive: $x = 4$.",
  "50": "**Step 1:** The two regular hexagons are similar, with apothems $9\\sqrt{3}$ and $6\\sqrt{3}$.\n**Step 2:** Perimeters are in the same ratio as any corresponding lengths: $\\frac{9\\sqrt{3}}{6\\sqrt{3}} = \\frac{3}{2}$."
 },
 "act2_3d_exam2": {
  "1": "**Step 1:** Line $q$ passes through $(-9, 0)$ and $(-3, 18)$: slope $= \\frac{18 - 0}{-3 + 9} = 3$, so $y = 3(x + 9) \\Rightarrow 3x - y = -27$.\n**Step 2:** Line $v$ passes through $(-4, 10)$ and $(0, 8)$: slope $= \\frac{8 - 10}{0 + 4} = -\\frac{1}{2}$, $y$-intercept $8$, so $y = -\\frac{1}{2}x + 8 \\Rightarrow x + 2y = 16$.\n**Step 3:** The system is $3x - y = -27$ and $x + 2y = 16$.",
  "2": "**Step 1:** In right $\\triangle ABC$ (right angle at $B$): $\\cos C = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{BC}{AC} = \\frac{15}{17}$.\n**Step 2:** $m\\angle C = \\cos^{-1}\\left(\\frac{15}{17}\\right) \\approx 28.1^\\circ$.\n**Step 3:** Similar triangles have equal corresponding angles, so $m\\angle F = m\\angle C \\approx 28^\\circ$.",
  "3": "**Step 1:** Slope: $m = \\frac{6 - 2}{-9 - 3} = \\frac{4}{-12} = -\\frac{1}{3}$.\n**Step 2:** Point-slope form through $(3, 2)$: $y - 2 = -\\frac{1}{3}(x - 3)$.\n**Step 3:** Multiply by $3$: $3y - 6 = -x + 3 \\Rightarrow x + 3y = 9$.",
  "4": "**Step 1:** Rewrite the second equation: $10y = -4x + 14 \\Rightarrow 4x + 10y = 14$.\n**Step 2:** Divide by $2$: $2x + 5y = 7$ — exactly the first equation.\n**Step 3:** The two equations describe the same line, so there are infinitely many solutions.",
  "5": "**Step 1:** $DC = AC - AD = 12 - 8 = 4$.\n**Step 2:** In a right triangle, the altitude to the hypotenuse gives: (leg)$^2$ = (adjacent segment) $\\times$ (hypotenuse). So $BC^2 = DC \\cdot AC = 4 \\times 12 = 48$.\n**Step 3:** $BC = \\sqrt{48} = 4\\sqrt{3}$.",
  "6": "**Step 1:** Cross-multiply: $5(2x + 3) = 2(5x + 3)$.\n**Step 2:** $10x + 15 = 10x + 6 \\Rightarrow 15 = 6$, which is never true.\n**Step 3:** The equation has no solution: no real numbers.",
  "7": "**Step 1:** The radius squared is $(-5)^2 + 12^2 = 25 + 144 = 169$, so the circle is $x^2 + y^2 = 169$.\n**Step 2:** Check each point: $(10, 3) \\to 109$; $(-12, 13) \\to 313$; $(11, 2\\sqrt{12}) \\to 121 + 48 = 169$ ✓; $(-8, 5\\sqrt{21}) \\to 64 + 525 = 589$.\n**Step 3:** Only $(11, 2\\sqrt{12})$ lies on the circle.",
  "8": "**Step 1:** In a cyclic quadrilateral, opposite angles are supplementary.\n**Step 2:** $\\angle A + \\angle C = 180^\\circ$: $80 + (y + 30) = 180 \\Rightarrow y = 70$.\n**Step 3:** $\\angle B + \\angle D = 180^\\circ$: $75 + (x - 10) = 180 \\Rightarrow x = 115$.",
  "9": "**Step 1:** A median joins a vertex to the midpoint of the opposite side, splitting that side into two equal bases.\n**Step 2:** The two smaller triangles share the same height from that vertex.\n**Step 3:** Equal bases and equal heights give equal areas — true for every triangle.",
  "10": "**Step 1:** The triangle is equilateral. Between the two tangent points on a side, the distance equals the distance between the two circle centers: $2r = 8$.\n**Step 2:** At each corner, the distance from the vertex to the tangent point is $r\\sqrt{3} = 4\\sqrt{3}$ (a $30$-$60$-$90$ triangle).\n**Step 3:** Side $= 8 + 2(4\\sqrt{3}) = 8 + 8\\sqrt{3}$; perimeter $= 3(8 + 8\\sqrt{3}) = 24 + 24\\sqrt{3}$.",
  "11": "**Step 1:** Let the width be $w$, so the length is $3w + 1$.\n**Step 2:** Area: $w(3w + 1) = 80 \\Rightarrow 3w^2 + w - 80 = 0 \\Rightarrow (3w + 16)(w - 5) = 0$.\n**Step 3:** $w = 5$ m (positive), so $l = 3(5) + 1 = 16$ m.",
  "12": "**Step 1:** After removing checkers: red $= 16 - 2 = 14$, black $= 16 - 1 = 15$.\n**Step 2:** Total left $= 29$.\n**Step 3:** $P(\\text{red}) = \\frac{14}{29}$.",
  "13": "**Step 1:** After $w$ weeks: Jasmine has $50 + 10w$, her sister has $80 + 7w$.\n**Step 2:** Jasmine has more when $50 + 10w > 80 + 7w \\Rightarrow 3w > 30 \\Rightarrow w > 10$.\n**Step 3:** The first whole week this happens is week $11$.",
  "14": "**Step 1:** At $0$ cars the salary is \\$2000, so the $y$-intercept is $2000$.\n**Step 2:** Each extra car adds \\$300: slope $= \\frac{2300 - 2000}{1 - 0} = 300$.\n**Step 3:** Equation $y = 300x + 2000$; the slope means Thomas earns an additional \\$300 for every car sold.",
  "15": "**Step 1:** $x$ is odd and positive; $-y$ is odd and positive.\n**Step 2:** $x - y = x + (-y)$ is the sum of two positive odd numbers, which is always positive and even.\n**Step 3:** (The other choices can be fractions, negative, or odd.)",
  "16": "**Step 1:** The altitude of an equilateral triangle splits it into two $30$-$60$-$90$ triangles with hypotenuse $6$ and short leg $3$.\n**Step 2:** Height $= 3\\sqrt{3}$ (or $h = \\frac{\\sqrt{3}}{2}s = \\frac{\\sqrt{3}}{2}(6)$).",
  "17": "**Step 1:** The potato lands when $f(x) = 0$: $x(1 - 0.0023x) = 0 \\Rightarrow x = \\frac{1}{0.0023} \\approx 435$ m.\n**Step 2:** The highest point is at the vertex, halfway: $x \\approx 217.4$.\n**Step 3:** $f(217.4) = 217.4 - 0.0023(217.4)^2 \\approx 108.7 \\approx 109$ m.",
  "18": "**Step 1:** $\\overline{AB} \\cong \\overline{CD}$ and $\\overline{BC} \\cong \\overline{DA}$ (all sides of a rhombus are equal).\n**Step 2:** $\\overline{AC} \\cong \\overline{AC}$ (shared side).\n**Step 3:** Three pairs of congruent sides: SSS.",
  "19": "**Step 1:** In a kite, the axis of symmetry passes through the midpoint of the other diagonal.\n**Step 2:** The horizontal diagonal goes from $x = a$ to $x = a + 4$.\n**Step 3:** Midpoint: $\\frac{a + (a + 4)}{2} = a + 2$, which is $P$'s $x$-coordinate.",
  "20": "**Step 1:** Vertices: $y = 3x$ meets $y = 0$ at $(0, 0)$; $y = -\\frac{1}{2}x + 4$ meets $y = 0$ at $(8, 0)$.\n**Step 2:** $3x = -\\frac{1}{2}x + 4 \\Rightarrow \\frac{7}{2}x = 4 \\Rightarrow x = \\frac{8}{7}$, $y = \\frac{24}{7}$.\n**Step 3:** Area $= \\frac{1}{2}(8)\\left(\\frac{24}{7}\\right) = \\frac{96}{7} = 13\\frac{5}{7}$.",
  "21": "**Step 1:** Compare with $(x - h)^2 + (y - k)^2 = r^2$.\n**Step 2:** $(x + 2)^2 = (x - (-2))^2$ and $(y - 1)^2$: center $(-2, 1)$.\n**Step 3:** $r^2 = 4 \\Rightarrow r = 2$.",
  "22": "**Step 1:** $2(l + w) = 34 \\Rightarrow l + w = 17$, and $lw = 60$.\n**Step 2:** Two numbers with sum $17$ and product $60$: $12$ and $5$.\n**Step 3:** Diagonal $= \\sqrt{12^2 + 5^2} = \\sqrt{169} = 13$.",
  "23": "**Step 1:** The $y$-terms are $9y$ and $-3y$.\n**Step 2:** Multiply equation B by $3$: $12x - 9y = 24$.\n**Step 3:** Adding to A: $(5x + 12x) + (9y - 9y) = 12 + 24$, so $y$ is eliminated.",
  "24": "**Step 1:** Let $u = x - 1$, so $x = u + 1$.\n**Step 2:** $g(u) = 3(u + 1)^2 + 5(u + 1) - 7 = 3u^2 + 6u + 3 + 5u + 5 - 7$.\n**Step 3:** $g(u) = 3u^2 + 11u + 1$, so $g(x) = 3x^2 + 11x + 1$.",
  "25": "**Step 1:** $\\sqrt{-48} = \\sqrt{16 \\cdot 3} \\cdot i = 4i\\sqrt{3}$.\n**Step 2:** $\\sqrt{-27} = \\sqrt{9 \\cdot 3} \\cdot i = 3i\\sqrt{3}$.\n**Step 3:** Sum $= 7i\\sqrt{3}$.",
  "26": "**Step 1:** Work from the inside out: from the table, $f(2) = 6$.\n**Step 2:** Then $g(f(2)) = g(6) = 9$.",
  "27": "**Step 1:** Rita is one of $10$ equally likely junior candidates: $P(\\text{Rita, given a junior wins}) = \\frac{1}{10}$.\n**Step 2:** $P(\\text{a junior wins}) = \\frac{1}{3}$.\n**Step 3:** $P(\\text{Rita}) = \\frac{1}{3} \\times \\frac{1}{10} = \\frac{1}{30}$.",
  "28": "**Step 1:** $\\left(\\frac{1}{2}\\right)^3 = \\frac{1}{8}$.\n**Step 2:** $f\\left(\\frac{1}{2}\\right) = \\frac{1/8}{4} = \\frac{1}{32}$.",
  "29": "**Step 1:** After the coach: $500 - 20 = 480$.\n**Step 2:** Ayleen gets $\\frac{1}{3}(480) = 160$, leaving $320$.\n**Step 3:** The other $4$ players split it: $\\frac{320}{4} = 80$, so Brenda receives \\$80.",
  "30": "**Step 1:** There are $14$ days, so the median is the average of the $7$th and $8$th values. With median $65$, these are $64$ and $66$ (the weekend values fill in around them).\n**Step 2:** Known repeats: $64$, $66$ and $77$ each appear twice. If a missing weekend value $Y$ is $6$, then $66$ appears three times and becomes the mode.\n**Step 3:** $59$, $64$ and $77$ cannot be made the unique mode while keeping the median at $65$, so the mode could be $66^\\circ$.",
  "31": "**Step 1:** $2\\pi r = 36\\pi \\Rightarrow r = 18$.\n**Step 2:** $A = \\pi r^2 = 324\\pi$.",
  "32": "**Step 1:** $\\overline{DE} \\parallel \\overline{BC}$, so $\\triangle ADE \\sim \\triangle ABC$.\n**Step 2:** $\\frac{AE}{AC} = \\frac{DE}{BC} = \\frac{4}{6} = \\frac{2}{3} \\Rightarrow AE = \\frac{2}{3}(9) = 6$.\n**Step 3:** $EC = 9 - 6 = 3$.",
  "33": "**Step 1:** Fit the boxes along each dimension: height $\\frac{9}{1.5} = 6$, width $\\frac{10}{1} = 10$, depth $\\frac{10}{2} = 5$.\n**Step 2:** Total $= 6 \\times 10 \\times 5 = 300$ boxes (same as volume $900 \\div 3 = 300$).",
  "34": "**Step 1:** $x = 6 > 5$, so use the first rule: $f(6) = \\sqrt{2(6) - 3} - 6$.\n**Step 2:** $= \\sqrt{9} - 6 = 3 - 6 = -3$.",
  "35": "**Step 1:** $f(5) = 5^2 - 3(5)$.\n**Step 2:** $= 25 - 15 = 10$.",
  "36": "**Step 1:** The order of letters gives the correspondence: $J \\leftrightarrow M$, $G \\leftrightarrow S$, $R \\leftrightarrow T$.\n**Step 2:** So $\\angle J \\cong \\angle M$, $\\angle G \\cong \\angle S$, $\\angle R \\cong \\angle T$ are always true.\n**Step 3:** $\\angle G \\cong \\angle T$ is not a corresponding pair, so it is not always true.",
  "37": "**Step 1:** Pedro: starts at $60$ and adds $5$ a week: $60 + 5t$.\n**Step 2:** Lea: starts at $80$ and adds $3$ a week: $80 + 3t$.\n**Step 3:** Equal collections: $60 + 5t = 80 + 3t$.",
  "38": "**Step 1:** An average of $80$ over $4$ tests needs a total of $320$.\n**Step 2:** Current total: $82 + 75 + 78 = 235$.\n**Step 3:** Needed score: $320 - 235 = 85$.",
  "39": "**Step 1:** Replacing $x$ with $x - h$ shifts a graph $h$ units right.\n**Step 2:** $y = |x - 2|$ is $y = |x|$ shifted right $2$ units (its vertex moves from $(0, 0)$ to $(2, 0)$).",
  "40": "**Step 1:** $500$ of the $1000$ tickets win a free movie ticket: probability $= \\frac{500}{1000} = \\frac{1}{2}$.\n**Step 2:** Expected number with $100$ tickets: $100 \\times \\frac{1}{2} = 50$ movie tickets.",
  "41": "**Step 1:** The hourly part is $20x$; the one-time charge is $30$.\n**Step 2:** $y = 20x + 30$.",
  "42": "**Step 1:** The line is vertical, crossing the $x$-axis at $6$: every point has $x = 6$.\n**Step 2:** Equation $x = 6$; a vertical line has undefined slope.",
  "43": "**Step 1:** The zeros of a quadratic are where its graph meets the $x$-axis.\n**Step 2:** Exactly one zero means the parabola just touches the $x$-axis at its vertex.",
  "44": "**Step 1:** Number of plates: $x + y = 15$.\n**Step 2:** Sum of diameters: $7x + 12y = 140$.",
  "45": "**Step 1:** $\\angle ABD \\cong \\angle CDB$ and $\\angle ADB \\cong \\angle CBD$ (alternate interior angles of parallel sides).\n**Step 2:** $\\overline{BD} \\cong \\overline{DB}$ is the side between those angles.\n**Step 3:** Angle–Side–Angle: ASA.",
  "46": "**Step 1:** $EC = AC - AE = 11.7 - 5.2 = 6.5$.\n**Step 2:** $\\overline{AB} \\parallel \\overline{CD}$ gives $\\triangle ABE \\sim \\triangle CDE$: $\\frac{AB}{CD} = \\frac{AE}{EC} = \\frac{5.2}{6.5} = 0.8$.\n**Step 3:** $AB = 0.8 \\times 10.5 = 8.4$.",
  "47": "**Step 1:** A parallelogram is a rectangle exactly when its diagonals are congruent.\n**Step 2:** So $\\overline{AC} \\cong \\overline{BD}$ proves $ABCD$ is a rectangle. (Perpendicular diagonals or a diagonal bisecting angles would make it a rhombus.)",
  "48": "**Step 1:** $y = 5$ is a horizontal line $5$ units above the $x$-axis.\n**Step 2:** It contains points with positive $x$ (quadrant I) and negative $x$ (quadrant II).",
  "49": "**Step 1:** Statement: if $p$ (radii equal), then $q$ (circles congruent).\n**Step 2:** The inverse is “if not $p$, then not $q$”.\n**Step 3:** “If the radii of two circles are unequal, then the circles are not congruent.”",
  "50": "**Step 1:** The markings show $ABCD$ is a rectangle (or has equal sides); a square needs both.\n**Step 2:** A rectangle whose diagonals are perpendicular is also a rhombus, hence a square.\n**Step 3:** So $\\overline{AC} \\perp \\overline{BD}$ is the needed information."
 },
 "act2_3d_exam4": {
  "1": "**Step 1:** Area of the full rectangle: $10 \\times 8 = 80\\text{ m}^2$.\n**Step 2:** The removed piece is a right triangle with legs $3$ and $4$: area $= \\frac{1}{2}(3)(4) = 6\\text{ m}^2$.\n**Step 3:** Remaining area $= 80 - 6 = 74\\text{ m}^2$.",
  "2": "**Step 1:** Slope formula: $m = \\frac{y_2 - y_1}{x_2 - x_1}$.\n**Step 2:** $m = \\frac{10 - 1}{7 - 4} = \\frac{9}{3} = 3$.",
  "3": "**Step 1:** Square: $4$ lines; rectangle (not square): $2$; equilateral triangle: $3$.\n**Step 2:** A circle is symmetric about every diameter — infinitely many lines, the greatest.",
  "4": "**Step 1:** The box is a square of area $144$, so its side is $\\sqrt{144} = 12$ in.\n**Step 2:** A circle fitting tightly has diameter $12$, so $r = 6$.\n**Step 3:** Area $= \\pi(6)^2 = 36\\pi\\text{ in}^2$.",
  "5": "**Step 1:** $B$ is the midpoint of $\\overline{AC}$ and $AC = 12$, so $AB = BC = 6$.\n**Step 2:** $A$ is between $B$ and $D$ and $C$ is between $B$ and $E$, so $D$ and $E$ lie on opposite sides of $B$: order $D, A, B, C, E$.\n**Step 3:** $DE = DB + BE = 20 + 8 = 28$.",
  "6": "**Step 1:** Check for a constant difference: $25000 \\to 15353$ in $3$ years is not a constant drop per year (later drops are smaller), so it is not linear.\n**Step 2:** Check for a constant ratio per year: $\\frac{15353.13}{25000} = 0.6141 = 0.85^3$, $\\frac{11092.63}{15353.13} = 0.7225 = 0.85^2$.\n**Step 3:** Each year the value is multiplied by $0.85$: it decreases exponentially by $15\\%$ per year.",
  "7": "**Step 1:** Parallel lines have equal slopes, so the new slope is $\\frac{2}{3}$.\n**Step 2:** The $y$-intercept is $-2$.\n**Step 3:** $y = \\frac{2}{3}x - 2$.",
  "8": "**Step 1:** Plan A: $C = 4t$ — starts at $0$ and rises by $4$ per hour.\n**Step 2:** Plan B: $C = 2t + 4$ — starts at $4$ and rises by $2$ per hour.\n**Step 3:** They are equal when $4t = 2t + 4 \\Rightarrow t = 2$ (cost $\\$8$). Graph C shows one line from $0$, one from $4$, crossing at $(2, 8)$.",
  "9": "**Step 1:** $9x^2 = (3x)^2$, $64 = 8^2$ and $48x = 2(3x)(8)$.\n**Step 2:** So $9x^2 - 48x + 64 = (3x - 8)^2$, and $3x - 8$ is a factor.",
  "10": "**Step 1:** Quadrant I has $(+,+)$ points and quadrant III has $(-,-)$ points.\n**Step 2:** A line through both rises from lower-left to upper-right, so its slope is positive.",
  "11": "**Step 1:** Direct variation means $y = kx$, so $\\frac{y}{x}$ is the same for every pair (and the line passes through the origin).\n**Step 2:** Table C: $\\frac{6}{-2} = -3$, $\\frac{-3}{1} = -3$, $\\frac{-12}{4} = -3$ — constant.\n**Step 3:** The other tables do not have a constant ratio.",
  "12": "**Step 1:** Order of operations: division first, $8 \\div 2 = 4$.\n**Step 2:** $6x + 4 - (4x - 5) = 6x + 4 - 4x + 5$.\n**Step 3:** $= 2x + 9$.",
  "13": "**Step 1:** Numerator: $7(4 - 3) = 7$ and $6\\left(\\frac{1}{2} - \\frac{1}{3}\\right) = 6 \\cdot \\frac{1}{6} = 1$, so the numerator is $7 - 1 = 6$.\n**Step 2:** Fraction: $\\frac{6}{6} = 1$.\n**Step 3:** $1 + 7(m - 1) = 1 + 7m - 7 = 7m - 6$.",
  "14": "**Step 1:** A triangle can have at most one obtuse angle, so the base angles are acute and $\\angle B$ is the vertex angle.\n**Step 2:** The equal legs of an isosceles triangle meet at the vertex angle.\n**Step 3:** So $AB = BC$.",
  "15": "**Step 1:** In a right triangle the hypotenuse is the longest side; $AB > AC$ means $AB$ is the hypotenuse and the right angle is at $C$.\n**Step 2:** The legs $AC$ and $BC$ are equal (isosceles), so $\\angle A = \\angle B$.\n**Step 3:** $\\angle A + \\angle B = 90^\\circ \\Rightarrow m\\angle B = 45^\\circ$.",
  "16": "**Step 1:** Let $r = 5k$ and $h = 7k$.\n**Step 2:** $V = \\pi r^2 h = \\pi(25k^2)(7k) = 175\\pi k^3 = 550$.\n**Step 3:** $k^3 = \\frac{550}{175\\pi} \\approx 1.0 \\Rightarrow k = 1$, so $r = 5$ in.",
  "17": "**Step 1:** $|2y + 1| = 7$ means $2y + 1 = 7$ or $2y + 1 = -7$.\n**Step 2:** $2y = 6 \\Rightarrow y = 3$; $2y = -8 \\Rightarrow y = -4$.\n**Step 3:** Solutions: $-4$ and $3$.",
  "18": "**Step 1:** $\\triangle ABC \\cong \\triangle FED$ gives $\\angle A = \\angle F = 35^\\circ$, $\\angle B = \\angle E = 30^\\circ$, $\\angle C = \\angle D = 180^\\circ - 65^\\circ = 115^\\circ$.\n**Step 2:** So $x - 45 = 35$, $x - 50 = 30$ and $x + 35 = 115$ all give $x = 80$.\n**Step 3:** $x + 35 = 65$ would give $x = 30$ — it cannot be used.",
  "19": "**Step 1:** Perimeter: $2[(x + 3) + 2x] = 51 \\Rightarrow 6x + 6 = 51 \\Rightarrow x = 7.5$.\n**Step 2:** Sides: $x + 3 = 10.5$ in and $2x = 15$ in.\n**Step 3:** Area $= 10.5 \\times 15 = 157.5\\text{ in}^2$.",
  "20": "**Step 1:** Distribute: $\\sqrt{6} \\cdot 5 + \\sqrt{6} \\cdot \\sqrt{6}$.\n**Step 2:** $= 5\\sqrt{6} + 6$.",
  "21": "**Step 1:** Total of the first $3$ exams $= 3 \\times 80 = 240$.\n**Step 2:** New total $= 240 + 70 = 310$.\n**Step 3:** New mean $= \\frac{310}{4} = 77.5$.",
  "22": "**Step 1:** Read the bars as frequencies of the values $1$ to $7$: $1, 5, 3, 2, 1, 4, 1$ — that is $17$ data values.\n**Step 2:** The median is the $9$th value. Cumulative counts: value $1 \\to 1$, value $2 \\to 6$, value $3 \\to 9$.\n**Step 3:** The $9$th value is $3$.",
  "23": "**Step 1:** The visitors double every $5$ years: $3, 6, 12$ (1970, 1975, 1980).\n**Step 2:** Continue: $24$ (1985), $48$ (1990), $96$ (1995), $192$ (2000) thousand.\n**Step 3:** About $192{,}000$ visitors in $2000$.",
  "24": "**Step 1:** $\\angle PRQ \\cong \\angle SRT$ (vertical angles).\n**Step 2:** If $\\overline{PQ} \\parallel \\overline{TS}$, then $\\angle P \\cong \\angle S$ (alternate interior angles with transversal $\\overline{PS}$).\n**Step 3:** Two pairs of equal angles: the triangles are similar by AA.",
  "25": "**Step 1:** $\\overline{AD}$ is common, $CD = DB$, and $\\angle ADC = \\angle ADB = 90^\\circ$ (AD is perpendicular to the plane), so $\\triangle ADC \\cong \\triangle ADB$ (SAS).\n**Step 2:** So $m\\angle DAC = m\\angle DAB = 35^\\circ$.\n**Step 3:** In right $\\triangle ADC$: $m\\angle ACD = 90^\\circ - 35^\\circ = 55^\\circ$.",
  "26": "**Step 1:** Subtract $b$: $ax > 2b + c$.\n**Step 2:** Divide by $a$ (positive, so the sign stays): $x > \\frac{c + 2b}{a}$.",
  "27": "**Step 1:** $f(2) = 4 + 6 + 2b + 3b = 10 + 5b = -20 \\Rightarrow b = -6$.\n**Step 2:** $f(x) = x^2 + 3x - 6x - 18 = x^2 - 3x - 18$.\n**Step 3:** $x^2 - 3x - 18 = (x - 6)(x + 3)$, zeros $-3$ and $6$.",
  "28": "**Step 1:** $x^0 = 1$, so the first factor is $3y^2$.\n**Step 2:** $(2x^2y^3)^2 = 4x^4y^6$.\n**Step 3:** $3y^2 \\cdot 4x^4y^6 = 12x^4y^8$.",
  "29": "**Step 1:** The ratio stays $4 : 6$, so new height $= 4k$ and new length $= 6k$.\n**Step 2:** Length is $5$ more than height: $6k - 4k = 5 \\Rightarrow k = 2.5$.\n**Step 3:** New length $= 6(2.5) = 15$ in.",
  "30": "**Step 1:** Simplify first: $\\frac{4x^5y^2}{15x^2y^3} = \\frac{4x^3}{15y}$.\n**Step 2:** Substitute: $\\frac{4(27)}{15(-2)} = \\frac{108}{-30}$.\n**Step 3:** $= -\\frac{18}{5}$.",
  "31": "**Step 1:** $2$ h $20$ min $= 2\\frac{1}{3} = \\frac{7}{3}$ h.\n**Step 2:** Speed $= 662 \\div \\frac{7}{3} = \\frac{662 \\times 3}{7} \\approx 283.7$.\n**Step 3:** About $284$ mph.",
  "32": "**Step 1:** Factor: two numbers with product $-4$ and sum $-3$: $-4$ and $1$.\n**Step 2:** $x^2 - 3x - 4 = (x - 4)(x + 1)$.\n**Step 3:** Zeros: $-1$ and $4$.",
  "33": "**Step 1:** Multiply top and bottom by $\\sqrt{3}$: $\\frac{2}{\\sqrt{3}} \\cdot \\frac{\\sqrt{3}}{\\sqrt{3}}$.\n**Step 2:** $= \\frac{2\\sqrt{3}}{3}$.",
  "34": "**Step 1:** The graph is a parabola (two turning directions would mean a cubic), so it is B or C.\n**Step 2:** It passes through $(2, 0)$ and $(3, -4)$. Test C: $2^2 - 9(2) + 14 = 0$ ✓ and $3^2 - 9(3) + 14 = -4$ ✓.\n**Step 3:** (B gives $0$ at $x = 3$, not $-4$.) The equation is $y = x^2 - 9x + 14$.",
  "35": "**Step 1:** From the table, each time $x$ increases by $1$, $y$ decreases by $2$.\n**Step 2:** The points lie on a line with slope $-2$ (steep and decreasing).\n**Step 3:** Graph B is the steep decreasing line.",
  "36": "**Step 1:** Rationalize: multiply by $\\frac{\\sqrt{y}}{\\sqrt{y}}$.\n**Step 2:** $\\frac{x}{\\sqrt{y}} \\cdot \\frac{\\sqrt{y}}{\\sqrt{y}} = \\frac{x\\sqrt{y}}{y}$.",
  "37": "**Step 1:** Translate: $9C = 5F - 160$.\n**Step 2:** $5F = 9C + 160 \\Rightarrow F = \\frac{9C + 160}{5}$.\n**Step 3:** $F = \\frac{9}{5}C + 32$.",
  "38": "**Step 1:** One rotation covers one circumference: $2\\pi r = 2(3.14)(14) = 87.92$ in.\n**Step 2:** $1$ mile $= 5280 \\times 12 = 63{,}360$ in.\n**Step 3:** Rotations $= \\frac{63360}{87.92} \\approx 720.7$, so $720$ complete rotations.",
  "39": "**Step 1:** Factor: $4 \\times 15 = 60$; numbers with product $60$ and sum $-16$: $-6$ and $-10$.\n**Step 2:** $4x^2 - 6x - 10x + 15 = 2x(2x - 3) - 5(2x - 3) = (2x - 3)(2x - 5)$.\n**Step 3:** $x = \\frac{3}{2}$ or $x = \\frac{5}{2}$.",
  "40": "**Step 1:** The two semicircles bulge to opposite sides, so a reflection would not map one onto the other: $0$ lines of symmetry.\n**Step 2:** Rotating $180^\\circ$ about the point where the diameters meet swaps the two semicircles exactly: $1$ point of symmetry.",
  "41": "**Step 1:** Both are right triangles (at $B$ and $E$) and $\\angle C \\cong \\angle F$, so $\\triangle ABC \\sim \\triangle DEF$ (AA).\n**Step 2:** Corresponding sides: $AB \\leftrightarrow DE$ and $BC \\leftrightarrow EF$.\n**Step 3:** $\\frac{BC}{AB} = \\frac{EF}{DE} \\Rightarrow \\frac{5}{8} = \\frac{EF}{4} \\Rightarrow EF = \\frac{5}{2}$ cm.",
  "42": "**Step 1:** $\\overline{XY}$ ($25$ in) is the hypotenuse and $XZ = 7$ in is a leg.\n**Step 2:** $ZY = \\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576}$.\n**Step 3:** $ZY = 24$ in.",
  "43": "**Step 1:** Multiply the coefficients and the radicands separately: $(2 \\cdot 3)\\sqrt{2 \\cdot 5}$.\n**Step 2:** $= 6\\sqrt{10}$.",
  "44": "**Step 1:** $4x^3y^2 \\cdot 2y^4x = 8x^4y^6$.\n**Step 2:** $4x^3y^2 \\cdot 6x^3y^7 = 24x^6y^9$.\n**Step 3:** Sum: $8x^4y^6 + 24x^6y^9$.",
  "45": "**Step 1:** The circle at $-1$ is open, so $-1$ itself is not included.\n**Step 2:** The arrow is shaded to the right (greater values).\n**Step 3:** $x > -1$.",
  "46": "**Step 1:** Interior angle sum: $(n - 2) \\cdot 180^\\circ = 540^\\circ$.\n**Step 2:** $n - 2 = 3 \\Rightarrow n = 5$: a pentagon.",
  "47": "**Step 1:** $\\overline{AC} \\perp \\overline{BD}$ at the center $O$, so the central angle $\\angle BOC = 90^\\circ$ and arc $BC = 90^\\circ$.\n**Step 2:** $\\angle BEC$ is an inscribed angle that intercepts arc $BC$.\n**Step 3:** $m\\angle BEC = \\frac{1}{2}(90^\\circ) = 45^\\circ$.",
  "48": "**Step 1:** The incline is a right triangle: base $67.2$ yd, hypotenuse $84$ yd.\n**Step 2:** $h = \\sqrt{84^2 - 67.2^2} = \\sqrt{7056 - 4515.84} = \\sqrt{2540.16}$.\n**Step 3:** $h = 50.4$ yd.",
  "49": "**Step 1:** The $48^\\circ$ angle is at the center (a central angle); $x$ is at the circle (an inscribed angle) and both intercept the same arc.\n**Step 2:** Inscribed angle $= \\frac{1}{2}$ central angle.\n**Step 3:** $x = \\frac{48^\\circ}{2} = 24^\\circ$.",
  "50": "**Step 1:** The big square (side $24$) contains $4$ congruent right triangles, each with hypotenuse $24$ and a $30^\\circ$ angle.\n**Step 2:** Legs: $24\\sin 30^\\circ = 12$ and $24\\cos 30^\\circ = 12\\sqrt{3} \\approx 20.785$.\n**Step 3:** The shaded square's side is the difference of the legs: $20.785 - 12 = 8.785$. Area $\\approx 8.785^2 \\approx 77.17$."
 },
 "act2_3d_exam5": {
  "1": "**Step 1:** A regular hexagon inscribed in a circle splits into $6$ equilateral triangles from the center.\n**Step 2:** So each side equals the radius: side $= 1$.\n**Step 3:** Perimeter $= 6 \\times 1 = 6$.",
  "2": "**Step 1:** Multiply both sides by $2$: $2A = bh$.\n**Step 2:** Divide by $b$: $h = \\frac{2A}{b}$.",
  "3": "**Step 1:** Drop the height $200$ from the top vertex; it splits the base into two parts.\n**Step 2:** Left part ($45^\\circ$): $\\frac{200}{\\tan 45^\\circ} = 200$. Right part ($60^\\circ$): $\\frac{200}{\\tan 60^\\circ} = \\frac{200}{\\sqrt{3}} \\approx 115.5$.\n**Step 3:** $x \\approx 200 + 115.5 = 315.5$.",
  "4": "**Step 1:** The arrows show $\\overline{AB} \\parallel \\overline{DF}$.\n**Step 2:** Alternate interior angles are congruent: $\\angle A \\cong \\angle F$ and $\\angle B \\cong \\angle D$; also the vertical angles at $C$ are equal.\n**Step 3:** Two pairs of equal angles: the triangles are similar by AA.",
  "5": "**Step 1:** Each interior angle of a regular pentagon is $\\frac{(5 - 2) \\cdot 180^\\circ}{5} = 108^\\circ$.\n**Step 2:** The diagonal cuts off the top isosceles triangle with apex $108^\\circ$: base angles $= \\frac{180 - 108}{2} = 36^\\circ$.\n**Step 3:** $x = 108^\\circ - 36^\\circ = 72^\\circ$.",
  "6": "**Step 1:** Opposite angles of a quadrilateral inscribed in a circle add to $180^\\circ$.\n**Step 2:** $3y + 3x = 180 \\Rightarrow x + y = 60$, and $5x + 2y = 180$.\n**Step 3:** Substitute $y = 60 - x$: $5x + 120 - 2x = 180 \\Rightarrow x = 20$, $y = 40$.",
  "7": "**Step 1:** Combine the exponents: $\\frac{a^n \\cdot a^m}{a^k} = a^{n + m - k}$.\n**Step 2:** $a^{n + m - k} = 1 = a^0 \\Rightarrow n + m - k = 0$.\n**Step 3:** $m + n = k$.",
  "8": "**Step 1:** The tent, the ground and the rope form a right triangle: hypotenuse $9$ ft, base $7$ ft.\n**Step 2:** Tent height $= \\sqrt{9^2 - 7^2} = \\sqrt{32} = 4\\sqrt{2}$ ft.\n**Step 3:** $\\tan\\theta = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{4\\sqrt{2}}{7}$.",
  "9": "**Step 1:** $CA = CB$ with a right angle at $C$: an isosceles right triangle with hypotenuse $AB = 4$.\n**Step 2:** The altitude $\\overline{CD}$ to the hypotenuse is also a median, so $D$ is the midpoint and $AD = DB = 2$.\n**Step 3:** $\\triangle ADC$ is also isosceles right, so $CD = AD = 2$.",
  "10": "**Step 1:** The lowest point (vertex) of the parabola is at $(3, 6)$, so $y = a(x - 3)^2 + 6$.\n**Step 2:** Only C has the vertex $(3, 6)$: $y = \\frac{1}{2}(x - 3)^2 + 6$.",
  "11": "**Step 1:** Step 2 gives two pairs of congruent sides: $AB \\cong DB$ and $EB \\cong BC$.\n**Step 2:** Step 3 gives the angle between them: $\\angle ABE \\cong \\angle DBC$ (vertical angles).\n**Step 3:** Side–Angle–Side: SAS.",
  "12": "**Step 1:** For an equilateral triangle, the inradius is $r = \\frac{s}{2\\sqrt{3}}$, so $s = 2\\sqrt{3}\\,r = 2\\sqrt{3} \\cdot 6\\sqrt{3} = 36$ ft.\n**Step 2:** Perimeter $= 3 \\times 36 = 108$ ft.\n**Step 3:** Bushes every $6$ ft around a closed loop (vertices included): $\\frac{108}{6} = 18$ bushes.",
  "13": "**Step 1:** Both legs are $3$ cm, so the triangle is an isosceles right triangle.\n**Step 2:** Its two acute angles are equal and add to $90^\\circ$.\n**Step 3:** $x = 45^\\circ$.",
  "14": "**Step 1:** The exterior angles of any convex polygon add to $360^\\circ$.\n**Step 2:** A regular pentagon has $5$ equal exterior angles: $\\frac{360^\\circ}{5} = 72^\\circ$.",
  "15": "**Step 1:** In $y = mx + b$, $m$ is the slope.\n**Step 2:** $y = \\frac{3}{4}x + 2 \\Rightarrow$ slope $= \\frac{3}{4}$ (the snow deepens $\\frac{3}{4}$ unit per hour).",
  "16": "**Step 1:** Distribute: $3(4 - x^2) = 12 - 3x^2$.\n**Step 2:** $12 - 3x^2 + 10 = -3x^2 + 22$.",
  "17": "**Step 1:** Exterior angle theorem: the exterior angle equals the sum of the two remote interior angles.\n**Step 2:** $2x = 30 + x \\Rightarrow x = 30^\\circ$.\n**Step 3:** $m\\angle ABD = 2x = 60^\\circ$.",
  "18": "**Step 1:** The two horizontal roads are parallel, so the angles at the lower crossing match angles $1$ and $2$: $71^\\circ$ and $43^\\circ$ (corresponding angles).\n**Step 2:** These two angles and $\\angle 3$ are the angles of the bottom triangle.\n**Step 3:** $m\\angle 3 = 180^\\circ - 71^\\circ - 43^\\circ = 66^\\circ$.",
  "19": "**Step 1:** Distribute: $2a - 2b - 3a + ab$.\n**Step 2:** Combine: $-a - 2b + ab$.",
  "20": "**Step 1:** $4x^2 = (2x)^2$, $9y^2 = (3y)^2$, $12xy = 2(2x)(3y)$.\n**Step 2:** Perfect square trinomial: $(2x - 3y)(2x - 3y)$.",
  "21": "**Step 1:** Isolate: $2|3x - 8| = 14 \\Rightarrow |3x - 8| = 7$.\n**Step 2:** $3x - 8 = 7 \\Rightarrow x = 5$; $3x - 8 = -7 \\Rightarrow x = \\frac{1}{3}$.\n**Step 3:** Solutions: $x = \\frac{1}{3}$ and $x = 5$.",
  "22": "**Step 1:** Same denominator: add the numerators: $\\frac{2 + 4}{3x} = \\frac{6}{3x}$.\n**Step 2:** Simplify: $\\frac{2}{x}$.",
  "23": "**Step 1:** $f(-2) = (-2)^2 - 3(-2) - 1$.\n**Step 2:** $= 4 + 6 - 1 = 9$.",
  "24": "**Step 1:** $\\sqrt{25 \\cdot 3^{16}} = \\sqrt{25} \\cdot \\sqrt{3^{16}} = 5 \\cdot 3^8$.\n**Step 2:** $3^8 = 6561$, so the value is $5 \\times 6561 = 32805$.",
  "25": "**Step 1:** Multiply each term by $8x$ and by $-3$: $32x^3 - 40x^2 + 48x$ and $-12x^2 + 15x - 18$.\n**Step 2:** Combine like terms: $32x^3 - 52x^2 + 63x - 18$.",
  "26": "**Step 1:** Raise each factor to the $3$rd power: $2^3 (x^2)^3 y^3$.\n**Step 2:** $= 8x^6y^3$.",
  "27": "**Step 1:** Distribute the minus sign: $x^2 + 4x + 4 - 5x^2 + x + 2$.\n**Step 2:** Combine: $-4x^2 + 5x + 6$.",
  "28": "**Step 1:** $\\sqrt{16x^6} = 4x^3$ and $\\sqrt{9x^4} = 3x^2$.\n**Step 2:** Product: $4x^3 \\cdot 3x^2 = 12x^5$.",
  "29": "**Step 1:** Add $6$: $3x < 24$.\n**Step 2:** Divide by $3$: $x < 8$.",
  "30": "**Step 1:** The diagonals of a rhombus are perpendicular, so they meet at $90^\\circ$.\n**Step 2:** In the right triangle at the top, the angles are $22^\\circ$, $90^\\circ$ and $x$.\n**Step 3:** $x = 180^\\circ - 90^\\circ - 22^\\circ = 68^\\circ$.",
  "31": "**Step 1:** Point-slope form: $y - 5 = \\frac{2}{3}(x + 2)$.\n**Step 2:** $y = \\frac{2}{3}x + \\frac{4}{3} + 5 = \\frac{2}{3}x + \\frac{19}{3}$.",
  "32": "**Step 1:** $81m^2 = (9m)^2$ and $4b^2 = (2b)^2$: a difference of squares.\n**Step 2:** $(9m - 2b)(9m + 2b)$.",
  "33": "**Step 1:** A circle inscribed in a square touches all four sides, so its diameter equals the side: $d = 20$.\n**Step 2:** $C = \\pi d = 20\\pi$.",
  "34": "**Step 1:** Large hexagon: apothem $a = 12\\sqrt{3}$, so its side is $\\frac{2a}{\\sqrt{3}} = 24$ and its area is $\\frac{3\\sqrt{3}}{2}(24)^2 = 864\\sqrt{3}$.\n**Step 2:** Small hexagon: apothem $b = 18$, so its side is $\\frac{2(18)}{\\sqrt{3}} = 12\\sqrt{3}$ and its area is $\\frac{3\\sqrt{3}}{2}(12\\sqrt{3})^2 = 648\\sqrt{3}$.\n**Step 3:** Shaded area $= 864\\sqrt{3} - 648\\sqrt{3} = 216\\sqrt{3}\\text{ cm}^2$.",
  "35": "**Step 1:** Pizza: $5$ at $p$ each $= 5p$. Soda: $3$ at $s$ each $= 3s$. Juice: $1$ at $j = j$.\n**Step 2:** Total $= 5p + 3s + j$.",
  "36": "**Step 1:** $x^2 = 6$.\n**Step 2:** $x = \\sqrt{6}$ or $x = -\\sqrt{6}$, i.e. $\\pm\\sqrt{6}$.",
  "37": "**Step 1:** In every row, weight $= 10 \\times$ width ($100 = 10 \\cdot 10$, $123 = 10 \\cdot 12.3$, …).\n**Step 2:** Width $= \\frac{160}{10} = 16$.",
  "38": "**Step 1:** A zero at $x = r$ gives the factor $(x - r)$.\n**Step 2:** Zeros $-2$ and $3$: $(x + 2)(x - 3)$.",
  "39": "**Step 1:** $C = 2\\pi R = 20$.\n**Step 2:** $R = \\frac{20}{2\\pi} = \\frac{10}{\\pi}$.",
  "40": "**Step 1:** Combine under one root: $\\sqrt{\\frac{8x^3}{27x}} = \\sqrt{\\frac{8x^2}{27}} = \\frac{2\\sqrt{2}\\,x}{3\\sqrt{3}}$.\n**Step 2:** Rationalize: $\\frac{2\\sqrt{2}\\,x \\cdot \\sqrt{3}}{3 \\cdot 3} = \\frac{2\\sqrt{6}}{9}x$.",
  "41": "**Step 1:** Common factor $2$: $2(9x^2 - 12x + 4)$.\n**Step 2:** $9x^2 - 12x + 4 = (3x - 2)^2$.\n**Step 3:** $2(3x - 2)(3x - 2)$.",
  "42": "**Step 1:** $\\tan x = \\frac{5}{12}$: opposite $5$, adjacent $12$, hypotenuse $\\sqrt{25 + 144} = 13$.\n**Step 2:** $\\sin x = \\frac{5}{13}$, $\\cos x = \\frac{12}{13}$.\n**Step 3:** $\\sin x + \\cos x = \\frac{17}{13}$.",
  "43": "**Step 1:** Subtract $3$: $-x \\ge 3$.\n**Step 2:** Multiply by $-1$ and flip the sign: $x \\le -3$.",
  "44": "**Step 1:** $\\frac{36}{48} = \\frac{3}{4}$.\n**Step 2:** $\\sqrt{\\frac{3}{4}} = \\frac{\\sqrt{3}}{2}$.",
  "45": "**Step 1:** $\\overline{CB}$ passes through the center, so it is a diameter; angles inscribed in a semicircle are right: $\\angle CAB = \\angle CDB = 90^\\circ$.\n**Step 2:** In $\\triangle ABC$: $\\angle ACB = 90^\\circ - 40^\\circ = 50^\\circ$.\n**Step 3:** In $\\triangle BCD$: $\\angle CBD = 90^\\circ - 55^\\circ = 35^\\circ$. Sum $= 85^\\circ$.",
  "46": "**Step 1:** Convert the time to minutes: $3$ h $20$ min $= 200$ min.\n**Step 2:** $y = 0.34(200) - 3 = 68 - 3 = 65$.",
  "47": "**Step 1:** Multiply the binomials first: $(2x - 1)(x + 2) = 2x^2 + 4x - x - 2 = 2x^2 + 3x - 2$.\n**Step 2:** Multiply by $-2x$: $-4x^3 - 6x^2 + 4x$.",
  "48": "**Step 1:** Total of the first $3$ marks: $3 \\times 80 = 240$. Total of the other $4$: $4 \\times 70 = 280$.\n**Step 2:** Overall mean $= \\frac{240 + 280}{7} = \\frac{520}{7}$.",
  "49": "**Step 1:** $f(x) - g(x) = (x^2 + 3) - (5x - 9)$.\n**Step 2:** $= x^2 + 3 - 5x + 9 = x^2 - 5x + 12$.",
  "50": "**Step 1:** Note: the figure as printed does not give enough information to derive $x$ rigorously (only the two segments $15$ and $25$ and two equal sides are marked).\n**Step 2:** The official answer key gives $x = 15$."
 },
 "act2_3d_exam6": {
  "1": "**Step 1:** Simplify the root: $\\sqrt{20} = 2\\sqrt{5}$, so $\\frac{30}{2\\sqrt{5}} = \\frac{15}{\\sqrt{5}}$.\n**Step 2:** Rationalize: $\\frac{15}{\\sqrt{5}} \\cdot \\frac{\\sqrt{5}}{\\sqrt{5}} = \\frac{15\\sqrt{5}}{5} = 3\\sqrt{5}$.",
  "2": "**Step 1:** An absolute value is never negative, so $2x \\ge 0$, i.e. $x \\ge 0$.\n**Step 2:** Case 1: $x - 3 = 2x \\Rightarrow x = -3$ — rejected ($x$ must be $\\ge 0$).\n**Step 3:** Case 2: $x - 3 = -2x \\Rightarrow 3x = 3 \\Rightarrow x = 1$. Check: $|1 - 3| = 2 = 2(1)$ ✓. Solution set $\\{1\\}$.",
  "3": "**Step 1:** Solve for $y$: $-3y = -5x + 9 \\Rightarrow y = \\frac{5}{3}x - 3$.\n**Step 2:** The slope is $\\frac{5}{3}$.",
  "4": "**Step 1:** Each term has a factor $-2x$: $-2x^3 + 4x^2 - 8x = -2x(x^2 - 2x + 4)$.\n**Step 2:** $x^2 - 2x + 4$ has discriminant $4 - 16 < 0$, so it cannot be factored further.",
  "5": "**Step 1:** A regular pentagon splits into $5$ congruent triangles from the center; area $= \\frac{5s^2}{4\\tan 36^\\circ}$.\n**Step 2:** $\\tan 36^\\circ \\approx 0.7265$, so $A \\approx \\frac{5(922)^2}{4(0.7265)} = \\frac{4{,}250{,}420}{2.906} \\approx 1{,}462{,}000$ ft$^2$.\n**Step 3:** About $1.5$ million square feet.",
  "6": "**Step 1:** $15\\% = 0.15$.\n**Step 2:** $0.15 \\times 8.95 = 1.3425$.\n**Step 3:** Closest choice: \\$1.35.",
  "7": "**Step 1:** From 9:30 to 11:00 is $1.5$ hours for $\\frac{1}{4}$ of the yard.\n**Step 2:** The remaining $\\frac{3}{4}$ takes $3 \\times 1.5 = 4.5$ hours.\n**Step 3:** Latest start: $6{:}30$ p.m. $- 4{:}30 = 2{:}00$ p.m.",
  "8": "**Step 1:** $\\frac{N}{10} \\approx 0.39 \\Rightarrow N \\approx 3.9$.\n**Step 2:** The closest choice is $4$.",
  "9": "**Step 1:** Let $b$ = boys, so girls $= 100 - b$.\n**Step 2:** Girl pianists $= 3 \\times$ boy pianists: $\\frac{1}{4}(100 - b) = 3 \\cdot \\frac{b}{8}$.\n**Step 3:** Multiply by $8$: $200 - 2b = 3b \\Rightarrow b = 40$. Boys who play: $\\frac{40}{8} = 5$.",
  "10": "**Step 1:** Division check: dividend $=$ divisor $\\times$ quotient $+$ remainder.\n**Step 2:** $A = 17 \\times 25 + 1 = 426$ and $B = 17 \\times 26 = 442$.\n**Step 3:** $B - A = 442 - 426 = 16$.",
  "11": "**Step 1:** Regular price $= 80\\%$ of list $= 0.80L$.\n**Step 2:** Sale price $= 90\\%$ of that $= 0.90 \\times 0.80L = 0.72L$.\n**Step 3:** The sale price is $72\\%$ of the list price.",
  "12": "**Step 1:** If the smallest side is $s$, the middle is $2s$ and the largest is $4s$.\n**Step 2:** Areas: $(4s)^2 = 16s^2$ and $s^2$.\n**Step 3:** Ratio $16 : 1$.",
  "13": "**Step 1:** Bob must make up $23$ cans and get ahead, i.e. collect more than $23$ extra cans in $3$ weeks.\n**Step 2:** Per week: more than $\\frac{23}{3} = 7\\frac{2}{3}$ cans.\n**Step 3:** Cans are whole numbers, so at least $8$ more cans per week.",
  "14": "**Step 1:** Add $2$ to both sides of $y = 2x - 4$.\n**Step 2:** $y + 2 = 2x - 2$.",
  "15": "**Step 1:** $5$ million $= 5{,}000{,}000$ and $25$ thousand $= 25{,}000$.\n**Step 2:** $\\frac{5{,}000{,}000}{25{,}000} = 200$ times.",
  "16": "**Step 1:** Two consecutive integers: $n$ and $n + 1$.\n**Step 2:** $S = 2n + 1$ — always odd. (It can be positive or negative, e.g. $-3 + (-2) = -5$.)",
  "17": "**Step 1:** Let length $= L$, width $= \\frac{L}{2}$.\n**Step 2:** The string is the perimeter: $2\\left(L + \\frac{L}{2}\\right) = 3L = 12$.\n**Step 3:** $L = 4$ m.",
  "18": "**Step 1:** Each member can bring up to $4$ guests, so each member accounts for up to $1 + 4 = 5$ people.\n**Step 2:** With $x$ members: at most $5x$ people.",
  "19": "**Step 1:** Similar triangles have the same three angles.\n**Step 2:** Triangle B's third angle: $180^\\circ - 30^\\circ - 70^\\circ = 80^\\circ$.\n**Step 3:** So Triangle A has angles $30^\\circ$, $70^\\circ$, $80^\\circ$ — $80^\\circ$ is the only listed choice.",
  "20": "**Step 1:** End-of-day price: $28\\frac{1}{4} - \\frac{3}{8} = 28.25 - 0.375 = 27.875$.\n**Step 2:** $40$ shares: $40 \\times 27.875 = 1115$ dollars.",
  "21": "**Step 1:** Solve for $y$: $3y = 6x + 10 \\Rightarrow y = 2x + \\frac{10}{3}$.\n**Step 2:** The slope is $2$.",
  "22": "**Step 1:** “Has a factor of $4$” and “multiple of $10$” means a multiple of $\\text{lcm}(4, 10) = 20$.\n**Step 2:** Multiples of $20$ from $1$ to $80$: $20, 40, 60, 80$.\n**Step 3:** $4$ numbers.",
  "23": "**Step 1:** Write as powers: $\\sqrt{x + 2} = (x + 2)^{\\frac{1}{2}}$ and $\\sqrt{(x + 2)^3} = (x + 2)^{\\frac{3}{2}}$.\n**Step 2:** Add exponents: $(x + 2)^{\\frac{1}{2} + \\frac{3}{2}} = (x + 2)^2$.",
  "24": "**Step 1:** Substitute $x = -3$: $2(9) + a(-3) - 4(-3) - 2a = 0$.\n**Step 2:** $18 - 3a + 12 - 2a = 30 - 5a = 0$.\n**Step 3:** $a = 6$.",
  "25": "**Step 1:** Write both with base $3$: $9^{2x - 1} = (3^2)^{2x - 1} = 3^{4x - 2}$.\n**Step 2:** $f(x) = g(x) \\Rightarrow 3^{4x - 2} = 3^{3x + 3} \\Rightarrow 4x - 2 = 3x + 3$.\n**Step 3:** $x = 5$.",
  "26": "**Step 1:** Percent increases multiply: growth factors $1.20$ and $1.30$.\n**Step 2:** $1.20 \\times 1.30 = 1.56$.\n**Step 3:** Combined increase: $56\\%$.",
  "27": "**Step 1:** $(i + 1)^2 = i^2 + 2i + 1 = -1 + 2i + 1 = 2i$.\n**Step 2:** $(i - 1)^2 = i^2 - 2i + 1 = -2i$.\n**Step 3:** $\\frac{2i}{-2i} = -1$.",
  "28": "**Step 1:** $(x + k)^2 = x^2 + 2kx + k^2$.\n**Step 2:** Match: $2k = 6 \\Rightarrow k = 3$.\n**Step 3:** $m = k^2 = 9$.",
  "29": "**Step 1:** $(a, b) \\to (a, b + 3)$ moves every point up $3$ units.\n**Step 2:** $y = x + 5$ shifted up $3$: $y = x + 8$.",
  "30": "**Step 1:** Candles per day: week $1$: $15$; each week adds $3$, so week $5$: $15 + 4 \\times 3 = 27$.\n**Step 2:** Five days: $27 \\times 5 = 135$ candles.",
  "31": "**Step 1:** Set equal: $-x^2 + 8 = -\\frac{1}{3}x + 5$.\n**Step 2:** $x^2 - \\frac{1}{3}x - 3 = 0$; discriminant $= \\left(\\frac{1}{3}\\right)^2 + 12 > 0$.\n**Step 3:** Two real solutions, so $2$ intersection points.",
  "32": "**Step 1:** Subtract $7$: $-3x < 9$.\n**Step 2:** Divide by $-3$ and flip the sign: $x > -3$.",
  "33": "**Step 1:** The largest cross section of a sphere is a great circle: $\\pi r^2 = 16\\pi \\Rightarrow r = 4$.\n**Step 2:** Surface area $= 4\\pi r^2 = 4\\pi(16) = 64\\pi$ units$^2$.",
  "34": "**Step 1:** Average $27$ over $5$ days: total $= 135$ minutes.\n**Step 2:** Day 1 was $31$, leaving $104$ for the other four days.\n**Step 3:** To make one day as long as possible, make the other three as short as possible ($23$ each): $104 - 69 = 35$ minutes.",
  "35": "**Step 1:** Isolate: $5|x - 2| = 15 \\Rightarrow |x - 2| = 3$.\n**Step 2:** $x - 2 = 3 \\Rightarrow x = 5$; $x - 2 = -3 \\Rightarrow x = -1$.",
  "36": "**Step 1:** Pollutant A increases at $\\frac{3}{2}$ units per day, so B decreases at $\\frac{3}{2}$ per day: slope $-\\frac{3}{2}$.\n**Step 2:** Starting amount on day $0$: $108$.\n**Step 3:** $y = -\\frac{3}{2}x + 108$.",
  "37": "**Step 1:** $\\tan^2 x = \\frac{\\sin^2 x}{\\cos^2 x}$, so $2\\tan^2 x \\cos^2 x = 2\\sin^2 x$.\n**Step 2:** Using $\\sin^2 x = 1 - \\cos^2 x$: $2(1 - \\cos^2 x)$.",
  "38": "**Step 1:** Factor: $x^3 - 4x^2 - 21x = x(x^2 - 4x - 21) = x(x - 7)(x + 3)$.\n**Step 2:** $x$-intercepts: $(0, 0)$, $(7, 0)$, $(-3, 0)$.\n**Step 3:** $(-7, 0)$ is not an $x$-intercept.",
  "39": "**Step 1:** The circle's center is $(-1, -4)$.\n**Step 2:** Slope of the radius to $(-4, 0)$: $\\frac{0 - (-4)}{-4 - (-1)} = \\frac{4}{-3} = -\\frac{4}{3}$.\n**Step 3:** A tangent is perpendicular to the radius: slope $= \\frac{3}{4}$.",
  "40": "**Step 1:** $\\left|\\frac{2 - x}{7}\\right| = \\left|\\frac{x + 3}{5}\\right|$ means $\\frac{2 - x}{7} = \\pm\\frac{x + 3}{5}$.\n**Step 2:** Plus: $5(2 - x) = 7(x + 3) \\Rightarrow 10 - 5x = 7x + 21 \\Rightarrow x = -\\frac{11}{12}$.\n**Step 3:** Minus: $5(2 - x) = -7(x + 3) \\Rightarrow 10 - 5x = -7x - 21 \\Rightarrow x = -\\frac{31}{2}$.",
  "41": "**Step 1:** Equation 1: slope $= \\frac{7 - 9}{-2 + 3} = -2$, through $(0, 3)$: $y = -2x + 3$.\n**Step 2:** Equation 2: slope $= \\frac{2 - 7}{-1 + 2} = -5$, through $(-2, 7)$: $y = -5x - 3$.\n**Step 3:** $-2x + 3 = -5x - 3 \\Rightarrow x = -2$ (both tables contain $(-2, 7)$).",
  "42": "**Step 1:** Square both sides: $\\sqrt{w} > 8 \\Rightarrow w > 64$.\n**Step 2:** Only $81$ is greater than $64$.",
  "43": "**Step 1:** Parallel lines have equal slopes (and different intercepts). Put each in $y = mx + b$ form.\n**Step 2:** C: $\\frac{1}{2}x - y = 2 \\Rightarrow y = \\frac{1}{2}x - 2$, and $2y = x - 1 \\Rightarrow y = \\frac{1}{2}x - \\frac{1}{2}$.\n**Step 3:** Both slopes are $\\frac{1}{2}$, so the lines are parallel.",
  "44": "**Step 1:** Distribute: $-mn + m^2 + mn - n^2$.\n**Step 2:** $-mn$ and $+mn$ cancel: $m^2 - n^2$.",
  "45": "**Step 1:** Triangle inequality: third side $c$ satisfies $7 - 2 < c < 7 + 2$, i.e. $5 < c < 9$.\n**Step 2:** Perimeter $= 9 + c$ is between $14$ and $18$ (not including them).\n**Step 3:** Only $16$ fits.",
  "46": "**Step 1:** A hexagonal prism has rectangular side faces standing on the hexagonal base.\n**Step 2:** A plane perpendicular to the base cuts these faces in vertical segments of the prism's height, with horizontal edges on the top and bottom faces.\n**Step 3:** The cross section is a rectangle.",
  "47": "**Step 1:** At half the height ($2$ in), similar triangles give half the radius: $\\frac{1.5}{2} = 0.75$ in.\n**Step 2:** Water volume $= \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(0.75)^2(2)$.\n**Step 3:** $\\approx 1.18 \\approx 1.2$ in$^3$.",
  "48": "**Step 1:** Square base with perimeter $36$: side $= 9$, base area $= 81$.\n**Step 2:** $V = \\frac{1}{3}Bh = \\frac{1}{3}(81)(15) = 405$ in$^3$.",
  "49": "**Step 1:** Let the other sides be $a \\le b$: $7 + a + b = 30 \\Rightarrow a + b = 23$, with $a \\ge 7$.\n**Step 2:** Triangle inequality: $b < 7 + a = 7 + (23 - b) \\Rightarrow 2b < 30 \\Rightarrow b < 15$. Also $b \\ge a \\Rightarrow b \\ge 11.5$.\n**Step 3:** $b$ can be $12$, $13$ or $14$: $3$ possible lengths.",
  "50": "**Step 1:** Both arcs are cut off by the same central angle, so each arc is the same fraction of its circle.\n**Step 2:** Arc length is proportional to the radius: $\\frac{EF}{CD} = \\frac{OE}{OC} = \\frac{6}{4} = 1.5$.\n**Step 3:** Arc $EF$ is $1.5$ times arc $CD$."
 },
 "act2_3d_exam7": {
  "1": "**Step 1:** The line of best fit rises from left to right.\n**Step 2:** As ACT scores increase, GPAs tend to increase: a positive correlation.\n**Step 3:** (“Must be true” rules out claims about a single student.)",
  "2": "**Step 1:** A cube net needs $6$ squares arranged so that no two faces overlap when folded.\n**Step 2:** Net B (a staircase of $1$–$3$–$2$ squares) folds so that each square becomes a different face.\n**Step 3:** The other nets have overlapping faces when folded.",
  "3": "**Step 1:** Distribute: $-2(3x + 1) = -6x - 2$.\n**Step 2:** $-4x - 8 - 6x - 2 - 10$.\n**Step 3:** $= -10x - 20$.",
  "4": "**Step 1:** Adding $5$ to every number in a list adds $5$ to the mean.\n**Step 2:** New mean $= 6 + 5 = 11$.",
  "5": "**Step 1:** Right triangle with legs $\\sqrt{x}$ and $2\\sqrt{5}$, hypotenuse $x$: $(\\sqrt{x})^2 + (2\\sqrt{5})^2 = x^2$.\n**Step 2:** $x + 20 = x^2 \\Rightarrow x^2 - x - 20 = 0 \\Rightarrow (x - 5)(x + 4) = 0$.\n**Step 3:** A length is positive: $x = 5$.",
  "6": "**Step 1:** Intersecting chords: the products of the two segments of each chord are equal.\n**Step 2:** $22 \\times 8 = 11 \\times x$.\n**Step 3:** $176 = 11x \\Rightarrow x = 16$.",
  "7": "**Step 1:** $r = \\frac{17}{2} = 8.5$.\n**Step 2:** $A = \\pi r^2 = 72.25\\pi$.",
  "8": "**Step 1:** The order of the letters gives the correspondence: $D \\leftrightarrow A$, $C \\leftrightarrow C$, $E \\leftrightarrow B$.\n**Step 2:** So angle $E$ corresponds to angle $B$.",
  "9": "**Step 1:** Slope $= \\frac{-6 - 4}{2 - 2} = \\frac{-10}{0}$ — division by zero.\n**Step 2:** Both points have $x = 2$: a vertical line, so the slope is undefined.",
  "10": "**Step 1:** Factor the denominator: $3x^3 + 27x = 3x(x^2 + 9)$.\n**Step 2:** $\\frac{3x^2}{3x(x^2 + 9)} = \\frac{x}{x^2 + 9}$.",
  "11": "**Step 1:** The angles of a quadrilateral add to $360^\\circ$.\n**Step 2:** $n + 2n + 3n + 4n = 10n = 360$.\n**Step 3:** $n = 36$.",
  "12": "**Step 1:** From the second equation: $x = 2 - 2y$.\n**Step 2:** Substitute: $3(2 - 2y) + 4 = -4y \\Rightarrow 10 - 6y = -4y \\Rightarrow y = 5$.\n**Step 3:** $x = 2 - 10 = -8$. Solution $(-8, 5)$.",
  "13": "**Step 1:** Read the bars as how often each value $1$–$5$ occurs: $4, 6, 5, 3, 4$ (total $22$).\n**Step 2:** The median is the average of the $11$th and $12$th values. Cumulative: value $1 \\to 4$, value $2 \\to 10$, value $3 \\to 15$.\n**Step 3:** Both the $11$th and $12$th values are $3$, so the median is $3$.",
  "14": "**Step 1:** The ramp is the hypotenuse ($50$ ft) and the height is opposite the $30^\\circ$ angle.\n**Step 2:** $h = 50\\sin 30^\\circ = 50 \\times 0.5 = 25.00$ ft.",
  "15": "**Step 1:** $\\sqrt{20} = 2\\sqrt{5}$, so $\\frac{30}{2\\sqrt{5}} = \\frac{15}{\\sqrt{5}}$.\n**Step 2:** $\\frac{15\\sqrt{5}}{5} = 3\\sqrt{5}$.",
  "16": "**Step 1:** Set equal: $-x^2 + 8 = \\frac{1}{3}x + 5 \\Rightarrow x^2 + \\frac{1}{3}x - 3 = 0$.\n**Step 2:** Discriminant $= \\frac{1}{9} + 12 > 0$: two real solutions.\n**Step 3:** $2$ points of intersection.",
  "17": "**Step 1:** Subtract $7$: $-3x < 9$.\n**Step 2:** Divide by $-3$ and flip the sign: $x > -3$.",
  "18": "**Step 1:** $(5x^3z^4y^{-2})^{-2} = 5^{-2}x^{-6}z^{-8}y^{4} = \\frac{y^4}{25x^6z^8}$.\n**Step 2:** $(3xy^4z^{-3})^3 = 27x^3y^{12}z^{-9} = \\frac{27x^3y^{12}}{z^9}$.\n**Step 3:** Multiply: $\\frac{27x^3y^{16}}{25x^6z^{17}} = \\frac{27y^{16}}{25z^{17}x^3}$.",
  "19": "**Step 1:** For $a, b > 0$: $\\sqrt{a^2b} = a\\sqrt{b}$ and $\\sqrt{ab^2} = b\\sqrt{a}$.\n**Step 2:** So the expression is $\\frac{a\\sqrt{b} + b\\sqrt{a}}{ab}$.",
  "20": "**Step 1:** Small cylinder: $r = 3$, $h = 10$: $V = \\pi(9)(10) = 90\\pi$.\n**Step 2:** Large cylinder: $r = 4$, $h = 20$: $V = \\pi(16)(20) = 320\\pi$.\n**Step 3:** $\\frac{320\\pi}{90\\pi} \\approx 3.56 \\approx 3.6$.",
  "21": "**Step 1:** Radii: $0.5$, $1$, $1.5$. Area inside the large circle but outside the small ones: $\\pi(1.5)^2 - \\pi(0.5)^2 - \\pi(1)^2 = \\pi(2.25 - 0.25 - 1) = \\pi$.\n**Step 2:** Square area $= 4^2 = 16$.\n**Step 3:** $P = \\frac{\\pi}{16} \\approx 0.196 \\approx 20\\%$.",
  "22": "**Step 1:** Convert to inches: hoop $13$ ft $= 156$ in, its shadow $3$ ft $4$ in $= 40$ in, boy $4$ ft $5$ in $= 53$ in.\n**Step 2:** Same sun angle, so heights and shadows are proportional: $\\frac{156}{40} = \\frac{53}{s}$.\n**Step 3:** $s = \\frac{53 \\times 40}{156} \\approx 13.6$ in $\\approx 1$ ft $1.5$ in.",
  "23": "**Step 1:** Adding $5$ to each number adds $5$ to the mean.\n**Step 2:** $6 + 5 = 11$.",
  "24": "**Step 1:** $y$-intercept $0$: the line passes through the origin.\n**Step 2:** Negative slope: going right it goes down, so it lies in quadrant II (left, up) and quadrant IV (right, down).",
  "25": "**Step 1:** Reflecting across the $y$-axis changes the sign of $x$: $(x, y) \\to (-x, y)$.\n**Step 2:** $(-3, 5) \\to (3, 5)$, $(-4, 2) \\to (4, 2)$, $(-1, 6) \\to (1, 6)$.",
  "26": "**Step 1:** Charlie chose cake and Marco had the same, so Marco: cake. Rob: brownies.\n**Step 2:** No one else had what Rob or Lauren had, so Lauren's dessert is unique: not cake (Marco, Charlie), not brownies (Rob), and not cookies (given).\n**Step 3:** Lauren ate ice cream.",
  "27": "**Step 1:** Factor: $x^2 - 100 = (x - 10)(x + 10)$, $x^2 + 4x - 60 = (x + 10)(x - 6)$, $x^2 - 6x = x(x - 6)$.\n**Step 2:** $\\frac{(x - 10)(x + 10)}{(x + 10)(x - 6)} \\cdot \\frac{x(x - 6)}{x - 10}$.\n**Step 3:** Everything cancels except $x$.",
  "28": "**Step 1:** Sum: $75 + 70 + 80 + 70 + 80 + 90 + 95 + 70 + 70 + 75 + 80 + 80 + 90 + 95 = 1120$; mean $= \\frac{1120}{14} = 80$.\n**Step 2:** Ordered: $70, 70, 70, 70, 75, 75, \\mathbf{80}, \\mathbf{80}, 80, 80, 90, 90, 95, 95$; median $= \\frac{80 + 80}{2} = 80$.\n**Step 3:** Mean $=$ Median.",
  "29": "**Step 1:** Write each fact as (day, hours worked).\n**Step 2:** Day $1$: $5$ h; day $5$: $4$ h; days $12$ and $14$: $6$ h.\n**Step 3:** $(1, 5), (5, 4), (12, 6), (14, 6)$.",
  "30": "**Step 1:** Doubling each year: $N = 6 \\cdot 2^t$.\n**Step 2:** After $9$ years: $6 \\cdot 2^9 = 6 \\cdot 512 = 3072$.",
  "31": "**Step 1:** Radii are $5k$, $8k$, $9k$; the middle one is $10$: $8k = 10 \\Rightarrow k = 1.25$.\n**Step 2:** Smallest radius $= 6.25$, largest $= 11.25$.\n**Step 3:** Distance between the circles $= 11.25 - 6.25 = 5$ cm.",
  "32": "**Step 1:** Along the $60$ cm side: $\\frac{60}{5} = 12$ squares; along the $45$ cm side: $\\frac{45}{5} = 9$.\n**Step 2:** Total: $12 \\times 9 = 108$ squares.",
  "33": "**Step 1:** Side lengths are in ratio $4 : 2 : 1$ (largest : middle : smallest).\n**Step 2:** Areas go with the square of the side: $4^2 : 1^2 = 16 : 1$.",
  "34": "**Step 1:** Expand: $(x + a)(x + b) = x^2 + (a + b)x + ab$.\n**Step 2:** Compare: $a + b = m > 0$ and $ab = n < 0$.\n**Step 3:** So $ab < 0$ and $a + b > 0$.",
  "35": "**Step 1:** Two squares aligned the same way can overlap in a smaller square or a non-square rectangle.\n**Step 2:** If one square is rotated $45^\\circ$ and its corner covers the other's corner, the overlap can be a triangle.\n**Step 3:** So I, II and III are all possible.",
  "36": "**Step 1:** “If a block is square, then it is not blue” has the contrapositive “if a block is blue, then it is not square”.\n**Step 2:** So a blue block must not be a square. (Being blue doesn't force it to be triangular, circular, or non-plastic.)",
  "37": "**Step 1:** $\\overline{AC}$ is a diameter, so $\\angle ABC = \\angle ADC = 90^\\circ$.\n**Step 2:** In $\\triangle ABC$: $\\angle BAC = 90^\\circ - 40^\\circ = 50^\\circ$, so $\\angle BAD = 50^\\circ + 55^\\circ = 105^\\circ$.\n**Step 3:** Opposite angles of a cyclic quadrilateral are supplementary: $\\angle BCD = 180^\\circ - 105^\\circ = 75^\\circ$.",
  "38": "**Step 1:** $P = (x, 3)$. Distance to $(8, 8)$: $(x - 8)^2 + (3 - 8)^2 = 13^2$.\n**Step 2:** $(x - 8)^2 = 169 - 25 = 144 \\Rightarrow x - 8 = \\pm 12$.\n**Step 3:** $x = 20$ or $x = -4$; the one less than $8$ is $-4$.",
  "39": "**Step 1:** Solve for $y$: $-3y = -5x + 9 \\Rightarrow y = \\frac{5}{3}x - 3$.\n**Step 2:** The slope is $\\frac{5}{3}$.",
  "40": "**Step 1:** $5(P + Q) = 30 \\Rightarrow P + Q = 6 \\Rightarrow P = 6 - Q$.\n**Step 2:** $P > 0$ means $6 - Q > 0$, i.e. $Q < 6$.\n**Step 3:** $Q$ cannot be $7$.",
  "41": "**Step 1:** Switching the two sides of an equation ($a = b \\Rightarrow b = a$) is the Symmetric Property of Equality.",
  "42": "**Step 1:** A conditional and its contrapositive always have the same truth value (as do the converse and the inverse).\n**Step 2:** So the conditional statement and its contrapositive are logically equivalent.",
  "43": "**Step 1:** A function gives each input $x$ exactly one output $y$ — the vertical line test.\n**Step 2:** A: vertical lines fail. B: a circle fails. C: the sideways V fails (two $y$-values for one $x$).\n**Step 3:** D passes: every vertical line meets it once.",
  "44": "**Step 1:** $\\overline{AB} \\parallel \\overline{CD}$ gives congruent alternate interior angles: $\\angle A \\cong \\angle D$ and $\\angle B \\cong \\angle C$.\n**Step 2:** The vertical angles where the segments cross are also equal.\n**Step 3:** Two pairs of congruent angles prove similarity: AA.",
  "45": "**Step 1:** Original: “If $p$ (Chris uses toothpaste X), then $q$ (he doesn't get cavities).”\n**Step 2:** Converse: swap them — “If $q$, then $p$”.\n**Step 3:** “If Chris doesn't get cavities, he uses toothpaste X.”",
  "46": "**Step 1:** The radius is $4 + 2 = 6$; the chord is $4$ units from the center.\n**Step 2:** A perpendicular from the center bisects the chord: half-chord $= \\sqrt{6^2 - 4^2} = \\sqrt{20} = 2\\sqrt{5}$.\n**Step 3:** $GB = 2 \\times 2\\sqrt{5} = 4\\sqrt{5}$.",
  "47": "**Step 1:** Boundary line $6A + 3S = 1500$ has a negative slope and is solid (because of $\\ge$).\n**Step 2:** Test the origin: $0 \\ge 1500$ is false, so shade the side away from the origin (above the line).\n**Step 3:** Numbers of people can't be negative, so the region stays in the first quadrant: graph D.",
  "48": "**Step 1:** $c < 0$: the parabola crosses the $y$-axis below the origin.\n**Step 2:** The vertex is at $x = -\\frac{b}{2}$; with $b > 0$ this is negative, so the vertex is left of the $y$-axis. The $x^2$ coefficient is $1$, so it opens up.\n**Step 3:** Graph A matches all three features.",
  "49": "**Step 1:** Rewrite the second equation: $10y = -4x + 14 \\Rightarrow 4x + 10y = 14$.\n**Step 2:** Divide by $2$: $2x + 5y = 7$ — the same as the first equation.\n**Step 3:** Identical lines: infinitely many solutions.",
  "50": "**Step 1:** The vertex is at $x = -\\frac{b}{2a} = -\\frac{8}{4} = -2$.\n**Step 2:** $y = 2(4) + 8(-2) + 7 = 8 - 16 + 7 = -1$, so the vertex is $(-2, -1)$; $a = 2 > 0$, so it opens up.\n**Step 3:** Graph C has its vertex at $(-2, -1)$."
 },
 "act2_3d_exam8": {
  "1": "**Step 1:** Clue 1: George, Wendy and Juanita did not bring lunch.\n**Step 2:** Clue 2: George ate the candy only if Juanita brought lunch — she didn't, so George did not eat it.\n**Step 3:** Clue 3: Wendy didn't bring lunch, so Juanita did not eat it. Clue 4: if Dashon ate it, Wendy brought lunch — she didn't, so Dashon did not eat it.\n**Step 4:** Clue 5: exactly one person ate it, so it was Wendy.",
  "2": "**Step 1:** Distribute: $3(4 - x^2) = 12 - 3x^2$.\n**Step 2:** Add $10$: $22 - 3x^2$.",
  "3": "**Step 1:** From the table the count doubles every hour: $1, 2, 4, 8, \\dots$ so $y = 2^t$.\n**Step 2:** After $10$ hours: $2^{10} = 1024$.",
  "4": "**Step 1:** King St. $\\parallel$ Monroe St., so the angles of the small triangle formed with Elk and Park Avenues are $71^\\circ$ and $43^\\circ$ (corresponding / alternate angles).\n**Step 2:** The angles of a triangle sum to $180^\\circ$: $m\\angle 3 = 180^\\circ - 71^\\circ - 43^\\circ = 66^\\circ$.",
  "5": "**Step 1:** Exterior angle theorem: $m\\angle ABD = m\\angle BDC + m\\angle DCB$.\n**Step 2:** Let $m\\angle DCB = x$: $2x = 30 + x \\Rightarrow x = 30^\\circ$.\n**Step 3:** $m\\angle ABD = 2(30^\\circ) = 60^\\circ$.",
  "6": "**Step 1:** Radius $= 2 + 4 = 6$ cm; the chord is $4$ cm from the center.\n**Step 2:** A radius perpendicular to a chord bisects it: half-chord $= \\sqrt{6^2 - 4^2} = \\sqrt{20} = 2\\sqrt{5}$.\n**Step 3:** Chord $= 2 \\times 2\\sqrt{5} = 4\\sqrt{5}$ cm.",
  "7": "**Step 1:** $\\sqrt{25 \\cdot 3^{16}} = \\sqrt{25} \\cdot \\sqrt{3^{16}}$.\n**Step 2:** $= 5 \\cdot 3^{8}$.",
  "8": "**Step 1:** Point-slope: $y + 5 = -2(x - 4)$.\n**Step 2:** $y + 5 = -2x + 8 \\Rightarrow 2x + y = 3$.",
  "9": "**Step 1:** $PQ$ is a diameter: $PQ = 2 \\times \\frac{5}{2} = 5$.\n**Step 2:** An angle inscribed in a semicircle is a right angle, so $\\angle PRQ = 90^\\circ$.\n**Step 3:** $PR^2 = 5^2 - 1^2 = 24 \\Rightarrow PR = \\sqrt{24}$.",
  "10": "**Step 1:** In step 4, $3^2$ is multiplied by $\\frac{1}{3^2}$ to get $1$.\n**Step 2:** A number times its reciprocal equals $1$: the inverse property of multiplication.",
  "11": "**Step 1:** Center = midpoint of the diameter: $\\left(\\frac{-1 + 5}{2}, \\frac{6 + 2}{2}\\right) = (2, 4)$.\n**Step 2:** $r^2 = (5 - 2)^2 + (2 - 4)^2 = 9 + 4 = 13$.\n**Step 3:** $(x - 2)^2 + (y - 4)^2 = 13$.",
  "12": "**Step 1:** Lengths scale by $3$, so areas scale by $3^2$.\n**Step 2:** The larger poster's area is $9$ times the smaller one's.",
  "13": "**Step 1:** Independent events: the first outcome does not change the probability of the second.\n**Step 2:** Tossing a coin twice — the coin has no memory. (Drawing without replacement, rain/wet sidewalk, etc. are dependent.)",
  "14": "**Step 1:** $2|3x - 8| = 14 \\Rightarrow |3x - 8| = 7$.\n**Step 2:** $3x - 8 = 7 \\Rightarrow x = 5$; $3x - 8 = -7 \\Rightarrow x = \\frac{1}{3}$.\n**Step 3:** Solutions: $x = 5$ and $x = \\frac{1}{3}$.",
  "15": "**Step 1:** $\\frac{\\sqrt{8x^3}}{\\sqrt{27x}} = \\sqrt{\\frac{8x^2}{27}} = \\frac{2\\sqrt{2}\\,x}{3\\sqrt{3}}$.\n**Step 2:** Rationalize: $\\frac{2\\sqrt{2}\\,x}{3\\sqrt{3}} \\cdot \\frac{\\sqrt{3}}{\\sqrt{3}} = \\frac{2\\sqrt{6}}{9}x$.",
  "16": "**Step 1:** $4x^2 = (2x)^2$, $9y^2 = (3y)^2$, and $12xy = 2(2x)(3y)$.\n**Step 2:** Perfect square: $(2x - 3y)^2$.",
  "17": "**Step 1:** $\\triangle EDC$: isosceles right with legs $DE = DC = 1$, so $EC = \\sqrt{2}$.\n**Step 2:** Square $ABCE$ has sides $\\sqrt{2}$.\n**Step 3:** Perimeter of $ABCDE$ (not counting the inside segment $EC$): $AB + BC + CD + DE + EA = \\sqrt{2} + \\sqrt{2} + 1 + 1 + \\sqrt{2} = 2 + 3\\sqrt{2}$.",
  "18": "**Step 1:** $x^2 = 2a$.\n**Step 2:** Two distinct real roots need $2a > 0$, i.e. $a > 0$ (then $x = \\pm\\sqrt{2a}$).",
  "19": "**Step 1:** $A = \\frac{1}{2}bh \\Rightarrow 2A = bh$.\n**Step 2:** Divide by $b$: $h = \\frac{2A}{b}$.",
  "20": "**Step 1:** The fence and the house wall are parallel, so the small and large right triangles are similar.\n**Step 2:** Distance from the ladder's foot: fence $1.5$ ft, house $1.5 + 3 = 4.5$ ft (3 times as far).\n**Step 3:** Height on the house $= 3 \\times 6 = 18$ ft.",
  "21": "**Step 1:** From the congruent triangles, $\\angle A \\cong \\angle E$; these are alternate interior angles for $\\overline{AB}$ and $\\overline{EF}$ with transversal $\\overline{AE}$.\n**Step 2:** Lines cut by a transversal with congruent alternate interior angles are parallel.",
  "22": "**Step 1:** Each block is $\\frac{1}{4}$ mile, so the siren reaches corners up to $2$ blocks away.\n**Step 2:** Maple and 6th is the central corner — every corner of Newton is within $2$ blocks of it.",
  "23": "**Step 1:** Similar solids with scale factor $3$ have volume ratio $3^3 = 27$.\n**Step 2:** The larger planter needs $27$ bags.",
  "24": "**Step 1:** Distribute the minus sign: $x^2 + 4x + 4 - 5x^2 + x + 2$.\n**Step 2:** Combine like terms: $-4x^2 + 5x + 6$.",
  "25": "**Step 1:** $(\\sqrt{16x^6})^2 = 16x^6$ and $(\\sqrt{4x^4})^2 = 4x^4$.\n**Step 2:** Product: $64x^{10}$.",
  "26": "**Step 1:** $162 = 16t^2 \\Rightarrow t^2 = \\frac{162}{16} = \\frac{81}{8}$.\n**Step 2:** $t = \\frac{9}{\\sqrt{8}} = \\frac{9}{2\\sqrt{2}} = \\frac{9\\sqrt{2}}{4}$ seconds.",
  "27": "**Step 1:** $\\overline{MO}$ goes from the center to the circle, so $MO = 2$ cm (a radius).\n**Step 2:** $\\overline{PN}$ is the other diagonal of rectangle $MNOP$, and a rectangle's diagonals are congruent, so $PN = 2$ cm.",
  "28": "**Step 1:** $f(-2) = (-2)^2 - 3(-2) - 1$.\n**Step 2:** $= 4 + 6 - 1 = 9$.",
  "29": "**Step 1:** “The first member ($x$) is $3$ less than half the second ($y$)”: $x = \\frac{1}{2}y - 3$.\n**Step 2:** Solve for $y$: $y = 2x + 6$ — slope $2$, $y$-intercept $6$.\n**Step 3:** Graph A is the steep rising line crossing the $y$-axis at $6$.",
  "30": "**Step 1:** With longest side $c$: obtuse when $a^2 + b^2 < c^2$ (and $a + b > c$).\n**Step 2:** $6^2 + 7^2 = 85 < 12^2 = 144$, and $6 + 7 > 12$, so $6, 7, 12$ is obtuse. ($5$-$12$-$13$ is right; the others are acute.)",
  "31": "**Step 1:** Perpendicular slope: negative reciprocal of $\\frac{2}{5}$ is $-\\frac{5}{2}$.\n**Step 2:** Through $(2, -2)$: $y + 2 = -\\frac{5}{2}(x - 2) = -\\frac{5}{2}x + 5$.\n**Step 3:** $y = -\\frac{5}{2}x + 3$.",
  "32": "**Step 1:** A tangent is perpendicular to the radius: $m\\angle HYX = 90^\\circ$.\n**Step 2:** The exterior angle at $X$ is $145^\\circ$, so $m\\angle HXY = 35^\\circ$.\n**Step 3:** $m\\angle XHY = 180^\\circ - 90^\\circ - 35^\\circ = 55^\\circ$.",
  "33": "**Step 1:** Rate of change = slope = change in area ÷ change in gallons.\n**Step 2:** From the graph, $1$ gallon covers $400$ ft$^2$: $\\frac{400 - 0}{1 - 0} = 400$ ft$^2$/gal.",
  "34": "**Step 1:** Let $p$ = postcard price, $e$ = envelope price: $14p + 5e = 12$ and $10p + 15e = 24.80$.\n**Step 2:** Multiply the first by $3$: $42p + 15e = 36$; subtract the second: $32p = 11.20 \\Rightarrow p = 0.35$.\n**Step 3:** $5e = 12 - 14(0.35) = 7.10 \\Rightarrow e = 1.42$, i.e. \\$1.42.",
  "35": "**Step 1:** When the net folds, the face two squares away in a straight line from red becomes its opposite face.\n**Step 2:** Opposite faces never touch; that face is blue, so blue is not adjacent to red.",
  "36": "**Step 1:** Expand: $(x + 7)^2 = x^2 + 14x + 49$.\n**Step 2:** $-4(x^2 + 14x + 49) - 6 = -4x^2 - 56x - 196 - 6$.\n**Step 3:** $= -4x^2 - 56x - 202$.",
  "37": "**Step 1:** Find two numbers with product $21 \\times (-20) = -420$ and sum $13$: $28$ and $-15$.\n**Step 2:** $21x^2 + 28x - 15x - 20 = 7x(3x + 4) - 5(3x + 4) = (3x + 4)(7x - 5)$.\n**Step 3:** So $7x - 5$ is a factor.",
  "38": "**Step 1:** Look at the solid from the front, from the right side, and from above, and record the visible squares in each direction.\n**Step 2:** Only view set D matches all three outlines of the figure.",
  "39": "**Step 1:** The terms increase by $6$: arithmetic with $d = 6$.\n**Step 2:** $a_n = a_3 + (n - 3)d = 0 + 6(n - 3) = 6n - 18$.",
  "40": "**Step 1:** In right $\\triangle ABC$: $\\cos C = \\frac{BC}{AC} = \\frac{15}{17}$, so $m\\angle C \\approx 28.1^\\circ$.\n**Step 2:** Similar triangles: $m\\angle F = m\\angle C \\approx 28^\\circ$.",
  "41": "**Step 1:** Slope $= \\frac{6 - 2}{-9 - 3} = -\\frac{1}{3}$.\n**Step 2:** $y - 2 = -\\frac{1}{3}(x - 3) \\Rightarrow 3y - 6 = -x + 3 \\Rightarrow x + 3y = 9$.",
  "42": "**Step 1:** Compare $y$-values at the same $x$: every $y$-value of $g$ is one third of $f$'s (same $x$-intercept, slope divided by $3$).\n**Step 2:** A vertical compression by $\\frac{1}{3}$: $g(x) = \\frac{1}{3}f(x)$.",
  "43": "**Step 1:** $DC = 12 - 8 = 4$.\n**Step 2:** Leg rule for the altitude to the hypotenuse: $BC^2 = DC \\cdot AC = 4 \\times 12 = 48$.\n**Step 3:** $BC = 4\\sqrt{3}$.",
  "44": "**Step 1:** Radius$^2 = (-5)^2 + 12^2 = 169$.\n**Step 2:** $(11)^2 + (2\\sqrt{12})^2 = 121 + 48 = 169$ ✓ — the other points give $109$, $313$, $589$.",
  "45": "**Step 1:** Contrapositive of “if $p$, then $q$” is “if not $q$, then not $p$”.\n**Step 2:** $p$: today is Friday; $q$: tomorrow is Saturday.\n**Step 3:** “If tomorrow is not Saturday, then today is not Friday.”",
  "46": "**Step 1:** At $x = 0$: $y = 8(0.25)^0 = 8$, so the $y$-intercept is $(0, 8)$.\n**Step 2:** (An exponential $8(0.25)^x$ never reaches $0$ — no $x$-intercept; its asymptote is $y = 0$; at $x = 2$, $y = 0.5$.)",
  "47": "**Step 1:** A graph is a function if every vertical line meets it at most once.\n**Step 2:** Only graph D passes the vertical line test.",
  "48": "**Step 1:** Place the two congruent semicircles on the same line, facing each other along the line.\n**Step 2:** The figure has $2$ lines of symmetry (the common line and the perpendicular bisector between them) and $1$ point of symmetry (the center).",
  "49": "**Step 1:** “The first member ($x$) is $3$ less than the second ($y$)”: $x = y - 3 \\Rightarrow y = x + 3$.\n**Step 2:** $y$-intercept: $(0, 3)$; $x$-intercept: $(-3, 0)$ — graph D.",
  "50": "**Step 1:** Correspondence from the names: $J \\leftrightarrow M$, $G \\leftrightarrow S$, $R \\leftrightarrow T$.\n**Step 2:** $\\angle G \\cong \\angle T$ pairs non-corresponding angles, so it is not always true."
 },
 "act2_3d_exam3": {
  "3": "**Step 1:** A plane is fixed by points that are not all on one line.\n**Step 2:** Two points only fix a line (infinitely many planes contain it).\n**Step 3:** Three non-collinear points determine exactly one plane — the minimum is $3$.",
  "11": "**Step 1:** From the figure, $\\triangle BDA$ has a right angle at $D$ with $BD = 3$ and $DA = 4$, so $BA = \\sqrt{3^2 + 4^2} = 5$.\n**Step 2:** Now $\\triangle ABC$ has sides $BA = 5$, $BC = 12$, $CA = 13$.\n**Step 3:** $5^2 + 12^2 = 25 + 144 = 169 = 13^2$, so by the converse of the Pythagorean theorem $\\angle ABC = 90^\\circ$: a right triangle.",
  "35": "**Step 1:** Vertical line test: a scatter plot is a function if no two points share the same $x$-value.\n**Step 2:** Graphs A and B have exactly one point above each $x$-value.\n**Step 3:** Graph C has two points with the same $x$-value, so it is not a function. Answer: Graphs A and B."
 }
};

